window.HEQIE_BOOK = {"title":"何切300问 · 中文对照全书","scope":"001—300 / 全部题目","source_title":"麻雀 傑作「何切る」300選","source_author":"G・ウザク 著，福地诚 编","questions":[{"id":1,"question_pdf":12,"answer_pdf":13,"question_printed":7,"answer_printed":8,"hand":["6p","7p","7p","8p","1s","1s","2s","2s","3s","4s","5s","7z","7z"],"draw":"5p","meta_ocr":"7巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora001.webp","indicator":"2z","discard":"2s","shanten":1,"comparisons":[["1s",18],["2s",18],["5s",14]],"translation":["兼顾碰中后听牌的机会和最终听牌形，选择进张最宽的形。切一索与切二索的有效牌枚数相同，但两者在形成双碰听时的和牌难易程度，以及能否因增加符数而升点等方面存在差别。","还要确认：如果像原书下方牌例那样以六筒和牌，可以按嵌张听来计算，因此能加计2符。"],"terms":["碰听","双碰听","嵌张","升点"],"action":"discard"},{"id":2,"question_pdf":12,"answer_pdf":13,"question_printed":7,"answer_printed":8,"hand":["6p","7p","7p","8p","1s","1s","2s","2s","3s","4s","5s","7z","7z"],"draw":"6p","meta_ocr":"束1局 7巡目 西家","banner_y":970,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora002.webp","indicator":"2z","discard":"5s","shanten":1,"comparisons":[["1s",18],["2s",18],["5s",17]],"translation":["保留最高打点形——二杯口的可能性。由于这手牌也有走七对子的机会，和切二索相比，有效牌实际上只少1枚，这一点也要确认。"],"terms":["二杯口","七对子"],"action":"discard"},{"id":3,"question_pdf":12,"answer_pdf":13,"question_printed":7,"answer_printed":8,"hand":["6p","7p","7p","8p","1s","1s","2s","2s","3s","4s","5s","7z","7z"],"draw":"7p","meta_ocr":"東1局 西家 7巡目","banner_y":1485,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora003.webp","indicator":"2z","discard":"8p","shanten":1,"comparisons":[["6p",13],["7p",13],["8p",13],["2s",12],["5s",8]],"translation":["以三暗刻为目标。若希望保留摸进赤牌的收益，就从外侧开始，切八筒；若更重视危险度，则从内侧开始，切六筒。"],"terms":["三暗刻","赤牌"],"action":"discard"},{"id":4,"question_pdf":14,"answer_pdf":15,"question_printed":9,"answer_printed":10,"hand":["2m","3m","8m","8m","4p","5p","5p","6p","7p","9p","5s","5s","6s"],"draw":"1m","meta_ocr":"6巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora004.webp","indicator":"2z","discard":"5s","shanten":1,"comparisons":[["9p",19],["5s",19],["5p",16],["6s",15]],"translation":["筒子部分是可接受三筒、六筒、八筒的“两面嵌张”复合形。选择更容易形成平和的结构。"],"terms":["两面嵌张","平和"],"action":"discard"},{"id":5,"question_pdf":14,"answer_pdf":15,"question_printed":9,"answer_printed":10,"hand":["2m","3m","8m","8m","4p","5p","5p","6p","7p","9p","5s","5s","6s"],"draw":"4m","meta_ocr":"束1局 東家 6巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora005.webp","indicator":"2z","discard":"9p","shanten":1,"comparisons":[["9p",19],["5s",19],["5p",16],["6s",15]],"translation":["筒子部分虽然是可接受三筒、六筒、八筒的“两面嵌张”复合形，但断幺九的打点高于平和，所以这里应确定断幺九，而非追求平和。这样也能应对碰五索等鸣牌。"],"terms":["两面嵌张","断幺九","鸣牌"],"action":"discard"},{"id":6,"question_pdf":14,"answer_pdf":15,"question_printed":9,"answer_printed":10,"hand":["3m","3m","4m","5m","5m","6p","6p","8p","3s","4s","6s","6s","7s"],"draw":"5s","meta_ocr":"东1局 東家 8巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora006.webp","indicator":"2p","discard":"8p","shanten":1,"comparisons":[["8p",18],["6s",14],["7s",11]],"translation":["切八筒能使有效牌枚数最大，但最后很可能形成嵌张听的一杯口。如果切六索，摸到七筒时再切六筒，就能转成进张更宽的一向听。","速度与向好形变化的可能性，该如何权衡？这里优先考虑能让手牌进入听牌的有效牌枚数，而非后续变化。","判断要点包括：自己是庄家；已经到了第8巡；断幺九已经确定，可以默听；若切六索，除了摸七筒之外，没有特别好的摸牌，大多数摸牌最后仍会回到切八筒。"],"terms":["一向听","一杯口","默听"],"action":"discard"},{"id":7,"question_pdf":16,"answer_pdf":17,"question_printed":11,"answer_printed":12,"hand":["4m","4m","0m","1p","3p","4p","5p","5p","6p","3s","4s","7s","8s"],"draw":"6m","meta_ocr":"6巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora007.webp","translation":["这是好形的两向听，但尚无确定的雀头，应最优先保留容易形成雀头的结构。即使摸到看似损失的二筒，也能把五筒固定为雀头。"],"discard":"1p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":8,"question_pdf":16,"answer_pdf":17,"question_printed":11,"answer_printed":12,"hand":["1m","3m","5m","1p","1p","2p","4p","0p","6p","6p","7p","7s","8s"],"draw":"9s","meta_ocr":"束1局 東家 6巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora008.webp","translation":["如果从这里先切五万，把本应留到听牌的五万提前打出，便能减弱他家对嵌二万的警惕；喜欢诱导待牌的人也可以这样处理。不过麻将终究要靠摸牌推进，正统选择仍是尽量保留容易形成两面听的结构。这手牌还能做平和，因此切二筒在打点上也不吃亏。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":9,"question_pdf":16,"answer_pdf":17,"question_printed":11,"answer_printed":12,"hand":["1m","3m","5m","1p","2p","3p","9p","9p","1s","2s","3s","6s","6s"],"draw":"7s","meta_ocr":"东1局 南家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"南家","turn":6,"special":"","dora_image":"images/dora009.webp","translation":["这里能看到123三色；若先补上嵌张，又有平和的可能，该如何取舍？推荐切五万，确定打点更高的三色。提前打出五万，也能减弱他家对嵌二万的警惕。若只想略微提高平和的机会，可以切六索；但即使这样，四种听牌进张中仍有三种最终要切五万。那么，不如先切五万，兼顾诱导他家放铳的可能。"],"discard":"5m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":10,"question_pdf":18,"answer_pdf":19,"question_printed":13,"answer_printed":14,"hand":["4m","6m","9m","9m","1p","1p","3p","3p","3s","4s","5s","6s","7s"],"draw":"0m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora010.webp","translation":["筒子保留为三张。切一筒后若摸四筒，确实能形成完全一向听；不过索子面子先完成的可能性更高。因此应重视最终听牌形，切三筒。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":11,"question_pdf":18,"answer_pdf":19,"question_printed":13,"answer_printed":14,"hand":["1m","2m","3m","4m","5p","6p","7p","8p","1s","2s","2s","2s","3s"],"draw":"3s","meta_ocr":"#1局 西家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora011.webp","translation":["单看有效牌枚数，切一索最宽；但把最终听牌形及平和、一杯口等打点因素一并考虑，切一万的期望值最高。原书所示的索子复合形很好，既能变化为“一个面子加一个雀头”，也能发展为一杯口。"],"discard":"1m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":12,"question_pdf":18,"answer_pdf":19,"question_printed":13,"answer_printed":14,"hand":["5m","5m","7m","8m","3p","4p","6p","7p","2s","4s","6s","6s","8s"],"draw":"6m","meta_ocr":"东1局 東家 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora012.webp","translation":["搭子过多。筒子与二索、六索、八索，无论切哪一处，有效牌都是24枚。筒子虽然有重复进张，但两面仍比嵌张更值得保留；考虑678三色，也不切八索；再考虑万子的延伸，应保留六索对子。逐项排除后，切二索较好。"],"discard":"2s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":13,"question_pdf":20,"answer_pdf":21,"question_printed":15,"answer_printed":16,"hand":["6m","7m","8m","1p","2p","3p","3p","5p","1s","2s","3s","7s","8s"],"draw":"6p","meta_ocr":"4巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora013.webp","translation":["切三筒、固定面子的进张最宽，但摸六筒时会被迫打出赤五筒。在只有一组独立两面的这一向听形中，是否固定雀头要看局面；像本题这样，存在被迫打出赤牌的可能时，固定雀头更有利。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":14,"question_pdf":20,"answer_pdf":21,"question_printed":15,"answer_printed":16,"hand":["2m","4m","8m","9m","6p","6p","6p","7p","3s","4s","7s","8s","9s"],"draw":"3m","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora014.webp","translation":["仅比较有效牌枚数，切七筒最多；但这样即使通过索子进张听牌，也只能听边张。这里切八万，保留宝牌九万：摸九万，以及五筒、八筒、七筒、二索、五索等，都有机会形成好形听牌。把宝牌作为浮牌留下有风险，但一旦重成雀头，收益也很大。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":15,"question_pdf":20,"answer_pdf":21,"question_printed":15,"answer_printed":16,"hand":["2m","2m","0m","3p","4p","6p","6p","2s","2s","5s","6s","7s","8s"],"draw":"7m","meta_ocr":"东1局 東家 6巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora015.webp","translation":["搭子过多，而且有三个雀头候选。五七万的嵌张虽然直接关系打点，却很弱，应以鸣牌为前提推进。容易碰的牌较多，因此把高位索子固定为一个面子；即使四连形延伸，断幺九也容易被破坏。切五索或八索差距不大；若兼顾567三色，以及摸六索后索子连接起来的机会，切八索较好。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":16,"question_pdf":22,"answer_pdf":23,"question_printed":17,"answer_printed":18,"hand":["1m","3m","4m","5m","5m","6m","6p","7p","3s","0s","7s","8s","8s"],"draw":"9s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora016.webp","translation":["摸四索、六索，可以转向断幺九加平和，并可能兼顾三色。虽然这样会失去摸二万直接完成一个面子的机会，但即使遇到这一反向进张，手牌也仍算向前推进了半步。"],"discard":"1m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":17,"question_pdf":22,"answer_pdf":23,"question_printed":17,"answer_printed":18,"hand":["1m","3m","5m","7m","8m","8m","9m","0p","6p","7p","5s","5s","6s"],"draw":"2m","meta_ocr":"束1局 7巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora017.webp","translation":["在一气通贯与三色之间选择。先切八万，摸一万、四万可形成平和加一气通贯；摸五万、五索、七索则可形成平和加赤1，没有明显的反向损失。与切五万、切五索相比，这样保留的有效牌多得多。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":18,"question_pdf":22,"answer_pdf":23,"question_printed":17,"answer_printed":18,"hand":["2p","2p","3p","3p","5p","5p","6p","6p","8p","5s","6s","6s","7s"],"draw":"7p","meta_ocr":"东1局 東家 5巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora018.webp","translation":["在有赤牌的麻将中，这里不应再朝清一色推进，实际是在切八筒与切六索之间选择。切八筒既维持七对子一向听，也观察索子组成两个面子的可能；摸到好的牌，还能转向断幺九。虽然会损失摸一筒的进张，但那会破坏断幺九，损失没有那么大；也可以把它视为碰二筒、三筒的替代路线。不必过分期待七对子，不过若已听牌就直接取听。反之，切六索后，之后摸到的索子都会变得无用，这一点很可惜。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":19,"question_pdf":24,"answer_pdf":25,"question_printed":19,"answer_printed":20,"hand":["4m","5m","5m","6m","6m","6m","3p","4p","4p","5p","6p","7p","7p"],"draw":"4p","meta_ocr":"8巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora019.webp","translation":["这是牌效率题，关键在于能否保留筒子的四面进张。乍看较难，只要发现万子摸三万至七万都能组成两个面子，而筒子的四筒与七筒属于重叠进张，就能得出答案。"],"discard":"7p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":20,"question_pdf":24,"answer_pdf":25,"question_printed":19,"answer_printed":20,"hand":["4m","5m","6p","8p","9p","9p","1s","1s","2s","3s","4s","6s","7s"],"draw":"7p","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora020.webp","translation":["涉及宝牌的连续形，基本原则是用宝牌的筋牌来做雀头。这样摸到宝牌三索时，可以与一索替换。也有人会想保留一索浮牌，但若先摸五万等牌形成完全一向听，或先摸入安全牌，之后再摸到宝牌就难处理了。"],"discard":"9p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":21,"question_pdf":24,"answer_pdf":25,"question_printed":19,"answer_printed":20,"hand":["3m","4m","4m","3p","3p","4p","5p","6p","7p","5s","5s","1z","1z"],"draw":"4p","meta_ocr":"东1局 東家 9巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora021.webp","translation":["若能碰出双东，自然没有问题，但已经第9巡，也要防备因为东是宝牌而迟迟无人打出的情况。这里切七筒，兼顾普通面子手与七对子。放弃筒子三面进张看似可惜，实际损失的只有八筒。虽然此时是七对子一向听，双东若出现仍要碰。"],"discard":"7p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":22,"question_pdf":26,"answer_pdf":27,"question_printed":21,"answer_printed":22,"hand":["1m","2m","3m","7m","2p","2p","8p","3s","3s","4s","5s","7s","9s"],"draw":"9s","meta_ocr":"3巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora022.webp","translation":["面子候选不足，正确选择是切掉作为浮牌最弱的八筒。"],"discard":"8p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":23,"question_pdf":26,"answer_pdf":27,"question_printed":21,"answer_printed":22,"hand":["3m","4m","0m","7m","7m","3p","4p","5p","6p","5s","5s","5s","7s"],"draw":"6m","meta_ocr":"束1局 東家 7巡目","banner_y":740,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora023.webp","translation":["自己是庄家，三色尚未确定，又已有一枚赤牌，应优先使有效牌枚数最大。如果为了万子三面听而切七万，摸二筒、七筒时反而无法取三面听；还要考虑摸二万后形成五面听的变化。实际上，切七索最容易形成多面听。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":24,"question_pdf":26,"answer_pdf":27,"question_printed":21,"answer_printed":22,"hand":["3m","4m","6m","6m","4p","4p","5p","8p","9p","1s","3s","7z","7z"],"draw":"0m","meta_ocr":"东1局 西家 3巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":3,"special":"","dora_image":"images/dora024.webp","translation":["把万子看成两个面子候选后，搭子就过多，应依照五组理论拆掉最弱的一组，即八九筒的边张。至于先切内侧还是外侧，即使马上摸七筒，本题形成七八筒两面搭子的改善也不算特别大，因此更重视危险度，先切内侧的八筒。"],"discard":"8p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":25,"question_pdf":28,"answer_pdf":29,"question_printed":23,"answer_printed":24,"hand":["2m","3m","4m","1p","1p","3p","3p","3p","4p","4p","5p","7s","7s"],"draw":"8s","meta_ocr":"束1月 北家 7巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"北家","turn":7,"special":"","dora_image":"images/dora025.webp","translation":["完整保留筒子复合形以获得宽进张，并把索子固定为两面。摸二筒、五筒时虽然需要切宝牌，但目前打点已经足够。若选择切一筒，作者戏称这是“断幺九病”。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":26,"question_pdf":28,"answer_pdf":29,"question_printed":23,"answer_printed":24,"hand":["5m","5m","6m","6p","7p","3s","4s","5s","5s","6s","6s","2z","2z"],"draw":"8p","meta_ocr":"東1局 東家 6巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora026.webp","translation":["为了摸赤五万也能听牌，很容易想切六索，但这样摸到宝牌三索时会难以处理。切五万的话，摸宝牌后可拆掉南对子，顺畅地转为断幺九。"],"discard":"5m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":27,"question_pdf":28,"answer_pdf":29,"question_printed":23,"answer_printed":24,"hand":["3m","0m","5m","6m","7m","7m","7m","3p","4p","5p","5s","6s","6s"],"draw":"8m","meta_ocr":"东1局 東家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora027.webp","translation":["万子形很复杂：摸六万可以做一杯口，摸四万可以做断幺九，但两者都是嵌张进张。这时的诀窍是保留复杂部分，先把原本强的部分整理清楚，也就是把索子固定为两面。选择搭子时犹豫不决，保留更复杂的那部分，通常就比较接近正确答案。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":28,"question_pdf":30,"answer_pdf":31,"question_printed":25,"answer_printed":26,"hand":["9m","9m","2p","3p","4p","6p","8p","3s","0s","7s","7s","4z","4z"],"draw":"4z","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora028.webp","translation":["这手牌应以门前为前提。切七索，优先固定赤五索这枚宝牌。自己是庄家，又有赤1，因此即使留下愚形，也可以直接立直。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":29,"question_pdf":30,"answer_pdf":31,"question_printed":25,"answer_printed":26,"hand":["6m","6m","6m","7m","8m","3p","4p","3s","0s","7s","7s","7z","7z"],"draw":"9m","meta_ocr":"束1局 6巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora029.webp","translation":["比起切七索、确保用上赤五索，这里更应优先保留碰中或将中变成暗刻的机会。在赤牌带额外祝仪的规则下，可能会觉得舍不得，但同样增加1番，前进速度却不同。若通过筒子进张听牌，基本选择是切赤五索，取双碰听立直。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":30,"question_pdf":30,"answer_pdf":31,"question_printed":25,"answer_printed":26,"hand":["2p","3p","4p","6p","8p","1s","3s","7s","7s","7s","4z","4z","4z"],"draw":"0s","meta_ocr":"东1局 東家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora030.webp","translation":["这是连高手也容易切一索的特殊形，答对值得自豪。候选为切八筒与切一索；仅看有效牌，切一索较宽，但这样摸四索时会被迫打出赤五索。把这点计入，两者的有效牌便没有差距。既然数量相同，应比较摸五索、六索、使其他部分完成面子之后的最终听牌形。嵌二索优于嵌七筒，所以正确选择是切八筒。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":31,"question_pdf":34,"answer_pdf":35,"question_printed":29,"answer_printed":30,"hand":["2m","3m","5m","5m","3p","3p","4p","3s","4s","5s","6s","8s","9s"],"draw":"4s","meta_ocr":"束1局 西家 5巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora031.webp","translation":["索子是可进二索、五索、七索的两面嵌张复合形；即使没有九索，七索仍能用上。这里开始瞄准三色。"],"discard":"9s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":32,"question_pdf":34,"answer_pdf":35,"question_printed":29,"answer_printed":30,"hand":["3m","4m","4m","4m","5p","6p","7p","8p","9p","6s","7s","9s","9s"],"draw":"9s","meta_ocr":"東1局 東家 巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora032.webp","translation":["庄家宝牌1，目标是抢先立直，直接选择进张最宽的形。摸八筒时虽然会打出宝牌九筒，但发生概率较低。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":33,"question_pdf":34,"answer_pdf":35,"question_printed":29,"answer_printed":30,"hand":["3m","3m","5m","2p","3p","4p","7p","8p","5s","6s","7s","7s","7s"],"draw":"6m","meta_ocr":"东1局 73 巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora033.webp","translation":["这是平和一向听，关键是拆三万对子还是七索对子。差别出现在五六万和七八筒这些未完成搭子重成对子、形成完全一向听时。例如摸八筒，切七索只增加三万、八筒两种进张，共4枚；切三万则增加六索、七索、八索三种，共7枚。之后索子若再变化，还能瞄准一杯口。基本原则是保留连接更紧密的牌。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":34,"question_pdf":36,"answer_pdf":37,"question_printed":31,"answer_printed":32,"hand":["6m","6m","6m","7m","9m","9m","1p","2p","3p","5p","6p","7s","7s"],"draw":"6m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora034.webp","translation":["还存在摸五万的变化，因此不杠，先拆掉一枚九万。如果摸八万，再暗杠六万并立直。庄家暗杠立直威力很大，作者开玩笑说这就像“接下来一直是我的回合”。"],"discard":"9m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":35,"question_pdf":36,"answer_pdf":37,"question_printed":31,"answer_printed":32,"hand":["4m","5m","6m","7m","2p","2p","3p","5p","6s","7s","7s","8s","8s"],"draw":"1p","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora035.webp","translation":["现在需要的是雀头，与其拆万子的四连形，不如依次整理二筒、五筒。这样万子或索子延伸时，也更容易把整手牌组合起来。像原书所示的一二二三筒形，基本可以优先固定面子。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":36,"question_pdf":36,"answer_pdf":37,"question_printed":31,"answer_printed":32,"hand":["4m","5m","6m","7m","4p","0p","6p","6p","7p","3s","4s","5s","5s"],"draw":"3p","meta_ocr":"东1局 東家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora036.webp","translation":["宝牌是二筒，因此容易想把筒子的三面进张固定下来；但切六筒的有效牌远少于其他切法，不必急着固定。切五索，无论有效牌总数还是能形成好形听牌的枚数，都更有利。"],"discard":"5s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":37,"question_pdf":38,"answer_pdf":39,"question_printed":33,"answer_printed":34,"hand":["3m","4m","5m","6m","1p","3p","7p","9p","9p","4s","5s","7s","8s"],"draw":"8p","meta_ocr":"4巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora037.webp","translation":["这是能看到平和的两向听。只看当前宽度，会考虑切三万或九筒；不过万子四连形和七八九九筒都容易形成雀头，应完整保留。换个角度看，这是搭子过多，切一筒拆掉嵌张即可。"],"discard":"1p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":38,"question_pdf":38,"answer_pdf":39,"question_printed":33,"answer_printed":34,"hand":["3m","3m","2p","3p","4p","5p","8p","9p","3s","3s","4s","7s","8s"],"draw":"9s","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora038.webp","translation":["切二筒、五筒的有效牌最多，但容易形成边七筒听牌。这里切三索更灵活：既保留摸七筒直接听牌的机会，也期待二三四五筒四连形的延伸。这是兼顾两面制作与速度的重要技巧。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":39,"question_pdf":38,"answer_pdf":39,"question_printed":33,"answer_printed":34,"hand":["3m","4m","3p","4p","4p","4p","1s","2s","2s","3s","4s","5s","5s"],"draw":"6s","meta_ocr":"东1局 東家 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora039.webp","translation":["虽然能看到断幺九、平和、三色，正确答案却是切三筒。很多人可能会拆一索，但无论摸入听牌进张中的二万、五万、四索、六索，若取听牌，最后都与现在切三筒得到相同的形。保留一索，还能应对意外摸入的宝牌二索，以及三索、五索。切三筒看似浪费，实际上十分出色。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":40,"question_pdf":40,"answer_pdf":41,"question_printed":35,"answer_printed":36,"hand":["2m","3m","4m","6m","7m","8m","4p","5p","1s","2s","3s","4s","5s"],"draw":"5m","meta_ocr":"7巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora040.webp","translation":["这里应确保用上赤五筒，断幺九也就基本确定。如果筒子雀头先形成，最终会是三面听。摸到宝牌三索时，可切二索处理。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":41,"question_pdf":40,"answer_pdf":41,"question_printed":35,"answer_printed":36,"hand":["1m","2m","3m","2p","3p","3p","5p","6p","7p","8p","5s","6s","7s"],"draw":"8s","meta_ocr":"束1局 西家 9巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":9,"special":"","dora_image":"images/dora041.webp","translation":["固定雀头，保留并利用两个四连形。若巡目还很早，摸五筒、八筒、五索、八索后形成的双碰听，也可以选择暂不取听，而把摸牌直接打掉。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":42,"question_pdf":40,"answer_pdf":41,"question_printed":35,"answer_printed":36,"hand":["3m","3m","3m","5m","7p","1s","1s","2s","0s","6s","7s","?","?"],"draw":"?","meta_ocr":"东1局 東家 7巡目","banner_y":1313,"original_only":true,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora042.webp","translation":["有人可能会切七筒，准备碰听或吃听；但这样七筒附近的牌之后都只能摸切。留下二索，吃到三四索固然很快，可即使把三四索共4枚按吃听两倍速度换算，也只是8枚。保留七筒，同样有8枚摸牌能形成两面听，其周边牌还可形成嵌张或双碰听。切二索的最终听牌形也更好。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":43,"question_pdf":42,"answer_pdf":43,"question_printed":37,"answer_printed":38,"hand":["4m","4m","4m","7m","3p","5p","7p","1s","1s","1s","3s","5s","5s"],"draw":"4p","meta_ocr":"6巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora043.webp","translation":["这是靠浮牌靠张听牌的题。暗刻旁边的浮牌不适合做这种靠张听牌，掌握这条原则即可。要知道，摸二索后的变则三面听，其实不如普通两面听。这里希望摸宝牌六万、六筒形成三面听，或摸五索做三暗刻；三索会妨碍三暗刻路线。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":44,"question_pdf":42,"answer_pdf":43,"question_printed":37,"answer_printed":38,"hand":["2m","3m","4m","3p","1s","2s","4s","5s","5s","6s","8s","9s","9s"],"draw":"3s","meta_ocr":"束1局 7巡目 南家","banner_y":912,"original_only":false,"round":"东1局","seat":"南家","turn":7,"special":"","dora_image":"images/dora044.webp","translation":["推荐切八索。若执着于一气通贯，不但有效牌变窄，还存在最终形变差、打出宝牌等多项缺点。希望利用三筒与五索的靠张，形成门前平和。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":45,"question_pdf":42,"answer_pdf":43,"question_printed":37,"answer_printed":38,"hand":["3m","4m","4p","5p","6p","6p","7p","8p","2s","4s","6s","7s","7s"],"draw":"8s","meta_ocr":"东1局 西家 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora045.webp","translation":["单看直接听牌枚数，切七索、固定面子更宽；但万子的两面正好能进宝牌与赤牌，值得保留。切二索比切八索、保留两嵌形更宽；除了直接听牌进张，摸六索或八索还能变化成很好的完全一向听，也保留筒子延伸的机会。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":46,"question_pdf":44,"answer_pdf":45,"question_printed":39,"answer_printed":40,"hand":["2m","4m","6m","7m","9m","9m","6p","7p","8p","1s","1s","4s","5s"],"draw":"5m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora046.webp","translation":["切九万，保留分别进三万、六万的两个嵌张。若先补上其中一个，最终就能形成平和。这是把两嵌形拉开后的结构，俗称“分离两嵌”。"],"discard":"9m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":47,"question_pdf":44,"answer_pdf":45,"question_printed":39,"answer_printed":40,"hand":["1m","1m","3m","4m","6m","8m","2p","2p","2p","5s","6s","9s","9s"],"draw":"5m","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora047.webp","translation":["一向听，切一万与八万的有效牌都是16枚；但切八万后，一万或九索变成暗刻时，在符数上更划算。还有靠近边端的双碰听通常更容易和牌这一优点。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":48,"question_pdf":44,"answer_pdf":45,"question_printed":39,"answer_printed":40,"hand":["4m","6m","7m","8m","9m","6p","6p","2s","2s","4s","4s","5s","5s"],"draw":"0m","meta_ocr":"东1局 東家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora048.webp","translation":["六七八索、六七八索组成两个面子，容易想从中切一张，但切六筒、二索、五索能形成两面听的枚数其实相同。更好的处理是让一枚六筒暂作浮牌，观察筒子延伸、远一点的三色机会，以及索子一杯口。不能切四索，否则会失去摸三索形成两面听的机会。不考虑赤牌时，牌效率排序为切六筒优于切五索，切五索又优于切四索。"],"discard":"6p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":49,"question_pdf":46,"answer_pdf":47,"question_printed":41,"answer_printed":42,"hand":["1m","3m","8m","8m","4p","6p","6p","2s","2s","4s","7s","8s","9s"],"draw":"5m","meta_ocr":"束1月 束家 6巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora049.webp","translation":["三个雀头候选，以门前为前提。依照“三雀头最弱理论”，拆对子比其他切法有2枚优势。切六筒能保留两种向两面变化的机会，因此正确。"],"discard":"6p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":50,"question_pdf":46,"answer_pdf":47,"question_printed":41,"answer_printed":42,"hand":["2m","4m","7m","8m","9m","2p","3p","5p","6p","2s","2s","4s","6s"],"draw":"6s","meta_ocr":"東1局 東家 4巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora050.webp","translation":["追求234三色，就必须拆掉五六筒两面，所以这里应放弃234三色，直接拆掉最弱搭子。又因为还存在赤五万与456三色的可能，先从外侧二万开始切。"],"discard":"2m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":51,"question_pdf":46,"answer_pdf":47,"question_printed":41,"answer_printed":42,"hand":["3m","4m","6m","2p","3p","4p","8p","8p","2s","3s","4s","7s","9s"],"draw":"0m","meta_ocr":"东1局 東家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora051.webp","translation":["推荐拆掉当前听牌。断幺九、平和、三色、赤牌进张，加上四连形带来的多种两面变化，条件如此齐全，拆听的优势已经很明显。嵌张立即立直在很多时候正确，但关键时刻也要懂得拆听。思路应是“正因为有赤牌，才更要保留容易自摸和牌的结构”，而不是“有赤牌就立直”。最差的是无役默听、只作暂时听牌；若只能取不能荣和的听牌，立即立直远好于默听。"],"discard":"9s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":52,"question_pdf":48,"answer_pdf":49,"question_printed":43,"answer_printed":44,"hand":["2m","4m","6m","6m","4p","5p","6p","7p","7p","3s","4s","6s","7s"],"draw":"8s","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora052.webp","translation":["切六万留下两嵌形，最终很容易变成嵌张听。切二万，期待筒子的延伸与变化。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":53,"question_pdf":48,"answer_pdf":49,"question_printed":43,"answer_printed":44,"hand":["7m","7m","1p","2p","2p","2p","3p","4p","3s","0s","5s","7s","8s"],"draw":"9s","meta_ocr":"東1局 西家 6巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora053.webp","translation":["切五索的进张最宽，但会留下微妙、难处理的形。切七万则会退回两向听，在有赤牌的麻将中完全不应考虑。实际是在一筒、三索、五索之间选择；犹豫时，以最终听牌形与赤牌进张为标准。这几种选择中，切一筒最好。"],"discard":"1p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":54,"question_pdf":48,"answer_pdf":49,"question_printed":43,"answer_printed":44,"hand":["2m","3m","4m","6m","7m","3p","4p","4p","5p","4s","5s","6s","8s"],"draw":"7s","meta_ocr":"东1局 東家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora054.webp","translation":["关键是把筒子作为三四四五的连续形使用，还是打掉三筒、五筒、固定雀头。手牌有连续形时，应优先固定面子；索子连续形本身很容易产生雀头。若通过万子进张听牌，最终会听包含宝牌八索的延边，完全可以接受。即使摸九索听牌而需切宝牌，门前断幺平和的打点也已足够。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":55,"question_pdf":50,"answer_pdf":51,"question_printed":45,"answer_printed":46,"hand":["3m","3m","4m","0m","5m","5m","6p","7p","7p","6s","7s","8s","9s"],"draw":"2m","meta_ocr":"4巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora055.webp","translation":["切七筒的有效牌枚数虽然较少，但无论通过哪种进张听牌，最终至少是两面听。同时兼顾宝牌自摸、赤牌以及万子多面听，期望值最高。"],"discard":"7p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":56,"question_pdf":50,"answer_pdf":51,"question_printed":45,"answer_printed":46,"hand":["2m","3m","4m","7m","5p","9p","9p","1s","2s","3s","3s","4s","6s"],"draw":"2s","meta_ocr":"束1局 東家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora056.webp","translation":["这是浮牌靠张题。因为处于平和一向听，应留下摸赤牌即可形成两面听的浮牌、能组成可进赤牌两面的浮牌，以及尽量容易形成靠近边端的最终听牌形的浮牌。如果摸赤五筒，再与其他浮牌交换即可。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":57,"question_pdf":50,"answer_pdf":51,"question_printed":45,"answer_printed":46,"hand":["4m","4m","0m","5m","4p","0p","7p","7p","4s","4s","4s","6s","6s"],"draw":"6p","meta_ocr":"东1局 東家 6巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora057.webp","translation":["能看到456三色，容易想整理万子的双重面子，但已有宝牌3，和牌优先于三色。这手牌其实也处于七对子一向听。切四筒不仅进张最多，还同时保留三暗刻、七对子与一杯口的可能。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":58,"question_pdf":52,"answer_pdf":53,"question_printed":47,"answer_printed":48,"hand":["3m","4m","5m","6m","2p","2p","2p","4p","2s","3s","4s","6s","8s"],"draw":"0m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora058.webp","translation":["切四筒虽更宽，但最终很容易变成嵌张听。这里拆掉六八索，拒绝愚形听牌，同时仍保留234三色。摸五索后能组成较宽的结构，因此从外侧八索开始切。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":59,"question_pdf":52,"answer_pdf":53,"question_printed":47,"answer_printed":48,"hand":["3m","4m","5m","6m","2p","2p","2p","4p","3s","4s","5s","6s","8s"],"draw":"0m","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora059.webp","translation":["与切八索相比，切四筒有多项优点：有效牌总数更多；万子两面先补完，也可以取延边听；即使最差形成嵌张听，默听时也还可以期待向好形变化。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":60,"question_pdf":52,"answer_pdf":53,"question_printed":47,"answer_printed":48,"hand":["2m","3m","2p","3p","4p","7p","7p","7p","6s","7s","8s","8s","9s"],"draw":"5p","meta_ocr":"东1局 東家 8巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora060.webp","translation":["单看进张，切二筒最宽，但二筒有助于形成很好的最终听牌形，这里应留下。接下来比较八索与九索：断幺九并不确定；五索与六索的枚数不同；反向进张出现时的补救能力也不同。综合考虑，切八索有利。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":61,"question_pdf":56,"answer_pdf":57,"question_printed":51,"answer_printed":52,"hand":["3m","4m","4m","4m","5p","6p","7p","8p","9p","6s","7s","9s","9s"],"draw":"9s","meta_ocr":"束1局 束家 巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora061.webp","translation":["保留不会被迫打出宝牌三万的结构。切六索后摸八索，也会被迫切宝牌，因此反向损失相同。这里应切九筒，最大程度保留三种赤牌与宝牌的进张。"],"discard":"9p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":62,"question_pdf":56,"answer_pdf":57,"question_printed":51,"answer_printed":52,"hand":["2m","3m","7m","7m","2p","3p","7p","8p","9p","6s","7s","8s","9s"],"draw":"2m","meta_ocr":"束1局 東家 4 巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora062.webp","translation":["赤牌进张优于需要两步变化才能完成的三色。切六索、观察789三色，是无赤规则的做法；要完成，必须先摸八万再摸九万，若顺序相反，平和会消失，价值不足。三色最终完成的概率很低，因此应把索子向内整理，保留赤牌进张。"],"discard":"9s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":63,"question_pdf":56,"answer_pdf":57,"question_printed":51,"answer_printed":52,"hand":["1m","2m","3m","0m","6m","7m","8m","3p","4p","2s","6s","7s","7s"],"draw":"3s","meta_ocr":"東1局 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora063.webp","translation":["已有两枚宝牌，直接切六索也是正确选择之一；但更推荐保留赤牌进张的贪心打法。除了赤牌，摸二索也能变成以宝牌作雀头的完全一向听。追求一气通贯价值较低：必须同时获得四万和九万；先摸四万尚好，先摸九万则微妙；即使遇到反向的四万进张，也可转向断幺九三色。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":64,"question_pdf":58,"answer_pdf":59,"question_printed":53,"answer_printed":54,"hand":["5m","6m","6m","7m","4p","5p","7p","2s","2s","4s","5s","6s","7s"],"draw":"9s","meta_ocr":"5巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora064.webp","translation":["摸切宝牌六万看似不错，但未必能完成567三色。面子候选已经足够，应该保留摸八索也能听牌的结构。即使这样，仍可以瞄准456三色。"],"discard":"7p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":65,"question_pdf":58,"answer_pdf":59,"question_printed":53,"answer_printed":54,"hand":["2m","3m","3m","1p","3p","3p","7p","4s","4s","4s","8s","4z","4z"],"draw":"2p","meta_ocr":"東1局 東家 3巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora065.webp","translation":["只看当前进张，切三万有利；但搭子不足，不必急着固定含宝牌的搭子。宝牌重成对子、摸四万等，都会带来高打点变化；还保留了七对子路线。原书提到，对此形的验证结果显示，留下三万在打点和速度两方面都更有利。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":66,"question_pdf":58,"answer_pdf":59,"question_printed":53,"answer_printed":54,"hand":["3m","4m","0m","8m","9m","9m","5p","6p","6p","1s","3s","8s","9s"],"draw":"6m","meta_ocr":"东1局 西家 3巡目","banner_y":1419,"original_only":false,"round":"东1局","seat":"西家","turn":3,"special":"","dora_image":"images/dora066.webp","translation":["搭子过多，而且才第3巡，不必急着固定筒子两面，先拆掉较弱的边张。五六六筒的形，尤其在摸六筒或七筒后会变强。若现在切六筒，就会让之后除四筒、七筒之外的筒子摸牌大多失去价值。"],"discard":"9s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":67,"question_pdf":60,"answer_pdf":61,"question_printed":55,"answer_printed":56,"hand":["2m","5m","5m","5m","5p","5p","8p","9p","9p","9p","2s","4s","6s"],"draw":"5s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora067.webp","translation":["分别考虑摸到内侧三万、七筒、三索时的形：万子形成两面，筒子形成变则三面听，索子形成三面听，最窄的是筒子。暗刻旁的浮牌，不适合用来做靠张听牌。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":68,"question_pdf":60,"answer_pdf":61,"question_printed":55,"answer_printed":56,"hand":["8m","8m","3p","4p","5p","6p","6p","7p","8p","9p","4s","6s","8s"],"draw":"3s","meta_ocr":"束1局 西家 9巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":9,"special":"","dora_image":"images/dora068.webp","translation":["第一希望是摸七索；若筒子延伸，则瞄准断幺九和平和。手里完全没有宝牌，要考虑宝牌可能已被他家利用；决定进攻，就应保留更容易鸣牌、行动的结构。无赤规则下可以切六筒追求一气通贯，但有赤规则下，应把自己视为比他家明显不利，选择最快的形。"],"discard":"9p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":69,"question_pdf":60,"answer_pdf":61,"question_printed":55,"answer_printed":56,"hand":["2m","3m","6m","7m","3p","4p","4p","9p","9p","3s","0s","7z","7z"],"draw":"3s","meta_ocr":"东1局 東家 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora069.webp","translation":["四个雀头候选，七对子两向听；但两面搭子多，也有宝牌与赤牌进张，因此不应朝七对子推进。这里搭子过多，应拆掉九筒对子，保留五个强组。不要因为九筒看似容易碰，就拆二三万两面，也不要半途而废地切四筒。"],"discard":"9p","shanten":3,"comparisons":[],"terms":[],"action":"discard"},{"id":70,"question_pdf":62,"answer_pdf":63,"question_printed":57,"answer_printed":58,"hand":["5m","6m","7m","7m","8m","5p","6p","6p","7p","8p","2s","4s","6s"],"draw":"8m","meta_ocr":"束1月 束家 6巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora070.webp","translation":["即使希望万子延伸，摸九万也会破坏断幺九。直接保留两嵌形、确定断幺九即可。不要像切二索那样盲目迷信两面。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":71,"question_pdf":62,"answer_pdf":63,"question_printed":57,"answer_printed":58,"hand":["3m","4m","5m","2p","2p","2p","4p","6p","3s","3s","3s","5s","7s"],"draw":"6m","meta_ocr":"東1局 西家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora071.webp","translation":["万子有横向延伸，也能摸宝牌三万重成对子，不宜拆。比较六筒与七索，差别在于摸七筒或八索后向上延伸时，是否能够确定断幺九。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":72,"question_pdf":62,"answer_pdf":63,"question_printed":57,"answer_printed":58,"hand":["3m","5m","5m","2p","2p","6p","8p","8p","6s","7s","8s","?","?"],"draw":"3s","meta_ocr":"东1局 東家 4巡目","banner_y":1313,"original_only":true,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora072.webp","translation":["当前进张虽以从五万或八筒对子中拆一枚更宽，但这些对子都能碰听，因此不考虑拆掉。实际只比较三万与六筒。看各自补充牌靠张后的形：三万摸二万后成为一四万两面，但一万会破坏断幺九，不能使用；六筒摸五筒后成为四七筒两面，再拆掉一个对子，便能保留这组两面搭子。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":73,"question_pdf":64,"answer_pdf":65,"question_printed":59,"answer_printed":60,"hand":["3m","3m","4m","4p","5p","6p","6p","6p","7p","6s","6s","7s","8s"],"draw":"9s","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora073.webp","translation":["按门前推进最宽。摸五筒或八筒时虽然会切掉宝牌，但能形成平和，立直后庄家满贯已确定，打点足够。为食断而切九索只会拖慢手牌。“断幺九病”要尽早改掉。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":74,"question_pdf":64,"answer_pdf":65,"question_printed":59,"answer_printed":60,"hand":["6m","8m","8m","1p","1p","4p","0p","5p","7p","9p","5s","7s","7s"],"draw":"9s","meta_ocr":"東1局 東家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora074.webp","translation":["庄家第4巡，四对子、七对子两向听。既要保留七对子，也不放弃摸宝牌后转为普通面子手的机会；根据局面，也可以考虑转向食断。真正明显的反向损失只有八筒。所谓“先把牌往内侧整理”，这里反而最灵活。"],"discard":"9p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":75,"question_pdf":64,"answer_pdf":65,"question_printed":59,"answer_printed":60,"hand":["2m","3m","6m","7m","4p","5p","5p","6p","7p","9p","0s","6s","6s"],"draw":"4m","meta_ocr":"东1局 西家 6巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora075.webp","translation":["切赤五索的进张最多，但摸八筒后仅做门前平和，吸引力不够。即使特意留下九筒，听牌时也很可能仍要切掉它；反而有很多变化能重新用上赤五索。这里先切九筒确定断幺九，再看下一张摸牌更好。若最终形成门前断幺平和听牌，打点已足够，可以切赤五索立直。"],"discard":"9p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":76,"question_pdf":66,"answer_pdf":67,"question_printed":61,"answer_printed":62,"hand":["3p","4p","4p","6p","6p","8p","8p","3s","4s","4s","5s","6s","7s"],"draw":"5p","meta_ocr":"6巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora076.webp","translation":["有效牌最多，也保留碰宝牌四索听牌的机会。若通过筒子进张听牌，就切宝牌四索，取三面听立直。"],"discard":"6p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":77,"question_pdf":66,"answer_pdf":67,"question_printed":61,"answer_printed":62,"hand":["3m","4m","0m","6m","8m","1p","1p","1p","7p","9p","7s","8s","8s"],"draw":"8s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora077.webp","translation":["索子形很好，应尽量发挥它的作用。实际是在切八万与九筒之间选择；万子相连，因此切八万更宽。最终听牌形，嵌八筒也优于嵌七万。注意不要漏看摸三万、六万可以听牌。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":78,"question_pdf":66,"answer_pdf":67,"question_printed":61,"answer_printed":62,"hand":["3m","4m","0m","7m","9m","1p","1p","1p","7p","9p","7s","9s","9s"],"draw":"9s","meta_ocr":"东1局 東家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora078.webp","translation":["这是有两个愚形的一向听。虽然希望最终留下七索、八索的变则双面听，但要这样就必须先补上万子或筒子的嵌张。这里切七索，选择有效牌最多的形。七九万或七九筒重成对子时，可取双碰听；嵌张先补完，则能从暗刻中拆一枚，选择另一处嵌张。789三色还需要三枚牌，现阶段并不现实。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":79,"question_pdf":68,"answer_pdf":69,"question_printed":63,"answer_printed":64,"hand":["1m","1m","3m","0m","5m","7m","3p","4p","5p","6p","7p","6s","7s"],"draw":"8p","meta_ocr":"6巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora079.webp","translation":["看似再变化一步就有三色，但要真正完成，必须在听牌前先摸二筒或五筒，最后还得以五索和牌，条件相当苛刻。这里直接选择有效牌最多的切法。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":80,"question_pdf":68,"answer_pdf":69,"question_printed":63,"answer_printed":64,"hand":["1m","1m","3m","0m","5m","7m","3p","4p","5p","6p","7p","6s","7s"],"draw":"5p","meta_ocr":"束1局 6巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora080.webp","translation":["567三色较容易完成，也能吃听。即使摸四万，门前平和加赤牌的打点已经足够，听牌就立即立直。通常不主动鸣牌，但要根据他家动作，把吃牌也纳入考虑。有效牌枚数以切七万最多，门前期望值却以切五万最高。"],"discard":"5m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":81,"question_pdf":68,"answer_pdf":69,"question_printed":63,"answer_printed":64,"hand":["2m","3m","4m","5m","2p","3p","5p","7p","6s","6s","6s","6s","7s"],"draw":"4p","meta_ocr":"東1局 西家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora081.webp","translation":["切六索的进张虽不算少，但多数时候会留下嵌张。完整保留筒子和索子，摸二筒、五筒可成两面，摸六筒可成三面听，摸五索、八索也能取延边。这里切万子既有最多进张，打点也更好。二万与五万之间，应把宝牌三万放在结构边缘，以便应对意外摸入的三万。宝牌应尽量放在边上。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":82,"question_pdf":70,"answer_pdf":71,"question_printed":65,"answer_printed":66,"hand":["6m","7m","8m","5p","5p","7p","9p","9p","3s","4s","6s","7z","7z"],"draw":"5s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora082.webp","translation":["拆筒子会大幅减少有效牌；与中组成双碰听已经足够，因此不必再执着于四连形，直接取最大进张。为应对摸到宝牌二索，切六索。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":83,"question_pdf":70,"answer_pdf":71,"question_printed":65,"answer_printed":66,"hand":["0m","5m","6m","7m","2p","2p","0s","6s","7s","8s","2p","?","?"],"draw":"?","meta_ocr":"東1局 東家 8巡目","banner_y":855,"original_only":true,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora083.webp","translation":["切五万与八索都剩6枚和牌张，但切五万有两个优点：摸六索后可变成三面听；自摸和牌时会因符数增加而升点。因此切五万正确。"],"discard":"5m","shanten":0,"comparisons":[],"terms":[],"action":"discard"},{"id":84,"question_pdf":70,"answer_pdf":71,"question_printed":65,"answer_printed":66,"hand":["1m","2m","3m","3m","4m","6m","7m","3p","5p","5p","5s","6s","7s"],"draw":"3m","meta_ocr":"东1局 東家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora084.webp","translation":["比较一万与三筒，两者进张只差1枚。切一万的反向损失较少，但听牌时有一半会成为愚形；切三筒容易做平和，而且最终必定至少是两面听。虽然吃听枚数不如切一万，碰听机会仍相同。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":85,"question_pdf":72,"answer_pdf":73,"question_printed":67,"answer_printed":68,"hand":["2m","2m","4m","4m","4p","5p","6p","7p","7p","0s","2z","2z","2z"],"draw":"5s","meta_ocr":"束1月 7巡目 南家","banner_y":339,"original_only":false,"round":"东1局","seat":"南家","turn":7,"special":"","dora_image":"images/dora085.webp","translation":["看似优柔寡断，但兼顾七对子与普通面子手的切四筒，既最宽也最灵活。不要漏看摸三万也可以听牌。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":86,"question_pdf":72,"answer_pdf":73,"question_printed":67,"answer_printed":68,"hand":["3m","3m","5m","6m","2p","3p","3p","5p","6p","2s","2s","3s","4s"],"draw":"0s","meta_ocr":"束1局 7巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora086.webp","translation":["现在有六组，搭子过多。不需要三个对子，因此拆掉没有补充牌的三万对子。"],"discard":"3m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":87,"question_pdf":72,"answer_pdf":73,"question_printed":67,"answer_printed":68,"hand":["2m","3m","4m","4m","4m","1s","1s","3s","4s","2z","2z","5z","5z"],"draw":"4s","meta_ocr":"东1局 東家 6巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora087.webp","translation":["若能碰到役牌兼宝牌的白，就很简单；但碰不到，局面会相当困难。这里把最高形看到四暗刻，推荐拆掉二三万。这样无论从哪一处鸣牌，都能保留强形；兼顾普通面子手与七对子，进张也最多。切四索乍看很快，但按五组理论，一旦再前进一步就会产生多余牌，速度其实微妙。先切二万或三万差距不大；为了下巡听牌时稍微保留更容易和到的外侧牌，推荐先切三万。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":88,"question_pdf":74,"answer_pdf":75,"question_printed":69,"answer_printed":70,"hand":["1m","2m","3m","1p","2p","3p","7p","8p","9p","1s","7s","8s","8s"],"draw":"4p","meta_ocr":"9巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora088.webp","translation":["宝牌是四筒，兼顾以宝牌作雀头与一气通贯。三色会确定留下愚形，还必须打出宝牌，因此不追。追求纯全带幺九更是效率过低。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":89,"question_pdf":74,"answer_pdf":75,"question_printed":69,"answer_printed":70,"hand":["0m","6m","1p","2p","3p","4p","6p","7p","8p","8p","9p","2z","2z"],"draw":"2z","meta_ocr":"東1局 東家 9巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora089.webp","translation":["宝牌指示牌七筒形成了瓶颈。若先切一筒、九筒，之后再摸万子重成对子，就可能进退两难。这里干脆切掉宝牌八筒应对。运气好可以完成一气通贯；即使摸一筒、四筒、六筒、九筒听牌，也直接立直。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":90,"question_pdf":74,"answer_pdf":75,"question_printed":69,"answer_printed":70,"hand":["3m","4m","4m","6m","8m","1p","3p","3p","6p","8p","8p","6s","7s"],"draw":"7m","meta_ocr":"东1局 東家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora090.webp","translation":["最想要断幺九，切一筒；最想要平和，切四万；最想要三色，切八筒。若三者全都想保留，仍是切一筒，期望值也最高。只要想象摸到七筒或八索之后的一向听形，就较容易判断。没解出这题，可以仔细阅读“一向听峰值理论”的讲解。"],"discard":"1p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":91,"question_pdf":78,"answer_pdf":79,"question_printed":73,"answer_printed":74,"hand":["1m","1m","2m","3m","3m","4m","4m","3s","4s","4s","5s","6s","8s"],"draw":"8s","meta_ocr":"8巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora091.webp","translation":["切八索，索子会留下两面嵌张复合形；但若要同时追求门前断幺平和，应切一万。万子是连续形，所以切一万与八索的有效牌枚数实际上相同。认识到这一点，才算完整答对。"],"discard":"1m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":92,"question_pdf":78,"answer_pdf":79,"question_printed":73,"answer_printed":74,"hand":["3m","3m","4m","5m","6m","6m","7m","1s","1s","1s","2s","2s","3s"],"draw":"7m","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora092.webp","translation":["二杯口受到三索枚数的限制：考虑宝牌指示牌后，三索只剩2枚。实战中宜一开始就切二索，瞄准平和和万子二五八万三面听。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":93,"question_pdf":78,"answer_pdf":79,"question_printed":73,"answer_printed":74,"hand":["5p","6p","6p","7p","8p","9p","5s","5s","6s","8s","4p","?","?"],"draw":"?","meta_ocr":"东1局 東家 8巡目","banner_y":1313,"original_only":true,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora093.webp","translation":["切八索拆听，似乎很快就能变成好形，但打点并不保证提高，因此直接取听牌。六筒与九筒之间选择九筒，是因为之后还能吃五筒、切八筒来换掉原来的嵌张听。再摸宝牌四索时，暂时取单骑听即可；此时提高1番的价值很大，宝牌四索及赤五索出现时，不要忘记碰。"],"discard":"9p","shanten":0,"comparisons":[],"terms":[],"action":"discard"},{"id":94,"question_pdf":80,"answer_pdf":81,"question_printed":75,"answer_printed":76,"hand":["5m","5m","8m","9m","1p","1p","2p","3p","3p","3p","4p","3s","4s"],"draw":"7m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora094.webp","translation":["选择最大进张，摸二筒还能形成一杯口。注意不要切一筒。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":95,"question_pdf":80,"answer_pdf":81,"question_printed":75,"answer_printed":76,"hand":["2m","3m","3m","4m","5m","7m","8m","1s","1s","2s","3s","4s","5s"],"draw":"1s","meta_ocr":"束1局 7巡目 西家","banner_y":740,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora095.webp","translation":["牌形取自片山政幸的漫画《牌贼！奥卡尔蒂》（竹书房）。索子包含宝牌进张，最终能形成四面听，已经很理想，不应拆。应从万子选择；切八万后，留下可进一万、四万、六万的两面嵌张复合形。切三万虽然有效牌总数略多，但能形成平和的枚数比切八万少。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":96,"question_pdf":80,"answer_pdf":81,"question_printed":75,"answer_printed":76,"hand":["2m","3m","3m","4m","5m","7m","3p","4p","5p","6p","6p","6p","7p"],"draw":"8m","meta_ocr":"東1局 西家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora096.webp","translation":["筒子的最终形已经很好，不宜拆。若偏重平和，似乎可以切八万，保留进一万、四万、六万的两面嵌张复合形；但这会失去包括赤五万在内的宝牌五万进张，代价过大。这里切三万，充分利用宝牌。与切八万相比，平和进张虽减少，但摸赤五万带来的打点提升非常大。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":97,"question_pdf":82,"answer_pdf":83,"question_printed":77,"answer_printed":78,"hand":["0m","6m","7m","8m","2p","2p","5p","6p","7p","8p","9p","6s","6s"],"draw":"8s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora097.webp","translation":["庄家且已有赤牌的一向听。已经到这个阶段，不再追求变化，直接取最大进张。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":98,"question_pdf":82,"answer_pdf":83,"question_printed":77,"answer_printed":78,"hand":["2m","3m","4m","6m","7m","4p","5p","6p","7p","7p","1s","3s","5s"],"draw":"0s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora098.webp","translation":["切一索与五索的有效牌相同，那么应确定断幺九，同时期待筒子或索子延伸。在有赤牌的麻将中，应重视“赤牌优于普通宝牌”；这种宝牌可以毫不犹豫地切掉。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":99,"question_pdf":82,"answer_pdf":83,"question_printed":77,"answer_printed":78,"hand":["4m","5m","6m","7m","9m","1p","3p","1s","1s","1s","2s","3s","4s"],"draw":"5s","meta_ocr":"东1局 東家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora099.webp","translation":["已有宝牌3，希望保留最大进张、抢先立直。切九万、二索、五索的有效牌最多；索子最终形已经很好，因此正确答案是切九万。许多人可能没注意到切九万与一筒的枚数不同：差别来自切九万后，摸四万、七万重成对子的进张。人们常只注意两面变化，却忽略重成对子的价值，也要记住这种模式。"],"discard":"9m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":100,"question_pdf":84,"answer_pdf":85,"question_printed":79,"answer_printed":80,"hand":["1m","1m","2m","3m","4m","4m","5m","6m","4p","1s","1s","2s","4s"],"draw":"5p","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora100.webp","translation":["有赤1，打点足够；若能抢先，愚形立直也值得，优先最大进张。现在还需三枚牌才能完成456三色，并不现实。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":101,"question_pdf":84,"answer_pdf":85,"question_printed":79,"answer_printed":80,"hand":["4m","5m","7m","8m","2p","2p","4p","0p","6p","7p","7p","3s","3s"],"draw":"9m","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora101.webp","translation":["切二筒连摸三筒也能听牌，进张最多。切七筒则会失去向完全一向听与一杯口变化的机会。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":102,"question_pdf":84,"answer_pdf":85,"question_printed":79,"answer_printed":80,"hand":["1s","1s","2s","3s","0s","7s","7s","8s","8s","8s","3z","3z","3z"],"draw":"8s","meta_ocr":"东1局 西家 9巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"西家","turn":9,"special":"","dora_image":"images/dora102.webp","translation":["打点已经足够，应重视最终听牌形；又已第9巡，也要考虑鸣牌带来的速度。最终最好的等待是六九索，应最大程度利用它。切赤五索后，无论从哪一处鸣牌，都较容易留下六九索听：一索、四索、六索、九索可吃，七索可碰；不是上家打出的一索也可以碰。虽然切赤牌令人犹豫，但现在更应提高和牌确定性；即使切赤五索，只要碰到宝牌一索，仍可达到跳满。"],"discard":"0s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":103,"question_pdf":86,"answer_pdf":87,"question_printed":81,"answer_printed":82,"hand":["1m","1m","3m","4m","0m","7m","8m","3p","5p","2s","2s","7s","9s"],"draw":"9s","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora103.webp","translation":["搭子过多，应拆掉最弱的一组，保留五组。先拆掉一枚一万。"],"discard":"1m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":104,"question_pdf":86,"answer_pdf":87,"question_printed":81,"answer_printed":82,"hand":["6m","7m","8m","3p","4p","4p","2s","2s","3s","3s","4s","5s","7s"],"draw":"5s","meta_ocr":"東1局 西家 5巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora104.webp","translation":["关键是能否发现摸六索会形成断幺平和听牌。单看有效牌，切七索多2枚；但能形成两面听的枚数相同，因为切七索后摸二索只能听嵌张。切四筒则必定形成平和。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":105,"question_pdf":86,"answer_pdf":87,"question_printed":81,"answer_printed":82,"hand":["4m","5m","6m","7m","1p","1p","0p","7p","8p","2s","4s","6s","7s"],"draw":"6p","meta_ocr":"东1局 東家 8巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora105.webp","translation":["仅看形，切二索似乎不错，但会退回两向听。虽然有两个四连形，第8巡再退到两向听仍太苛刻。已有宝牌3，鸣牌也能满贯，因此以鸣牌三色为主线。从万子或筒子的四连形中拆一枚即可；比较最终形、三色完成率与赤牌进张，拆筒子都更有利。之后若摸三万，不要忘记与二四索替换。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":106,"question_pdf":88,"answer_pdf":89,"question_printed":83,"answer_printed":84,"hand":["3m","4m","4m","5m","5p","6p","6p","6p","6s","7s","7s","8s","9s"],"draw":"9s","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora106.webp","translation":["切七索的进张最多，但无法充分发挥筒子三面进张；切九索则有效牌不足。综合宽度、打点和最终形，切四万最平衡。"],"discard":"4m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":107,"question_pdf":88,"answer_pdf":89,"question_printed":83,"answer_printed":84,"hand":["6m","7m","5p","7p","7p","2s","2s","3s","3s","4s","0s","7s","7s"],"draw":"8s","meta_ocr":"東1局 西家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora107.webp","translation":["宝牌2，远处还有三色可能。拒绝会破坏断幺九的九索，保留既能靠张、也能鸣牌的结构。切七筒、固定含宝牌搭子也是一种选择，但最后听嵌六筒的可能性会很高。已经确保赤1，基本应先切八索。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":108,"question_pdf":88,"answer_pdf":89,"question_printed":83,"answer_printed":84,"hand":["6m","6m","6m","3p","4p","0p","6p","7p","9p","9p","9p","6s","7s"],"draw":"8s","meta_ocr":"东1局 西家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora108.webp","translation":["很多人可能切六万或九筒，取二五八筒三面听；但切三筒后，是四七八筒的变则三面听，以四筒或七筒和牌时会因符数增加而升点。荣和2600与3200、自摸1000／2000与1300／2600的差距并不小。实战可按情形选择，但期望值排序为切三筒优于切六万，切六万又优于切九筒。切三筒后立直。"],"discard":"3p","shanten":0,"comparisons":[],"terms":[],"action":"riichi"},{"id":109,"question_pdf":90,"answer_pdf":91,"question_printed":85,"answer_printed":86,"hand":["3p","3p","4p","6p","7p","8p","9p","3s","3s","4s","6s","7s","8s"],"draw":"6p","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora109.webp","translation":["看似要把宝牌进张固定为两面，实际上是道陷阱题。切三索的话，摸五筒也能做断幺九。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":110,"question_pdf":90,"answer_pdf":91,"question_printed":85,"answer_printed":86,"hand":["6m","7m","8m","8m","8m","3p","4p","4p","0p","6p","8p","2s","2s"],"draw":"3s","meta_ocr":"東1局 東家 6巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora110.webp","translation":["筒子是可进二筒、五筒、七筒的两面嵌张复合形。若要做平和，切二索看似不错；但万子其实是面子与雀头相连的结构，切八筒最宽，摸五万、八万也可听牌，期望值最高。另一个优点是比切二索更容易做断幺九。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":111,"question_pdf":90,"answer_pdf":91,"question_printed":85,"answer_printed":86,"hand":["7m","8m","8m","9m","9m","1p","1p","2p","4p","4p","5p","6p","0s"],"draw":"6s","meta_ocr":"东1局 西家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora111.webp","translation":["似乎可以切八万，观察筒子延伸；但只要摸七万，万子就非常稳固，不宜提前拆。拆万子还会增加被迫打出宝牌九万的可能，应尽量留到最后。于是应拆二四筒嵌张。两者比较，切二筒、摸五筒只会产生两面搭子，不如切四筒后摸三筒直接完成面子。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":112,"question_pdf":92,"answer_pdf":93,"question_printed":87,"answer_printed":88,"hand":["3m","4m","6m","8m","1p","2p","2p","3p","3p","5p","6p","4s","5s"],"draw":"7m","meta_ocr":"6巡目 束1月 南家","banner_y":339,"original_only":false,"round":"东1局","seat":"南家","turn":6,"special":"","dora_image":"images/dora112.webp","translation":["搭子过多。选择拆哪一组时，比起一杯口，更应考虑断幺九与三色。先以二筒作雀头，切三筒；若之后产生其他雀头候选，就切一枚二筒，把一二三筒固定为面子即可。"],"discard":"3p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":113,"question_pdf":92,"answer_pdf":93,"question_printed":87,"answer_printed":88,"hand":["2m","3m","3m","4m","1p","2p","3p","6p","7p","7p","7p","7s","8s"],"draw":"8s","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora113.webp","translation":["现在没有宝牌。如果兼具赤牌与宝牌的赤五筒仍有机会摸到，就应尽量保留最终听五八筒的结构。把万子固定为一个面子后，不仅索子面子完成能听五八筒，摸到第四枚七筒时，也能取五八筒听牌。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":114,"question_pdf":92,"answer_pdf":93,"question_printed":87,"answer_printed":88,"hand":["3m","3m","4m","0m","9m","1p","4p","0p","5p","6p","5s","8s","1z"],"draw":"1z","meta_ocr":"东1局 東家 巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":1,"special":"","dora_image":"images/dora114.webp","translation":["从孤立牌中选择。八索虽是宝牌筋，但能组成两面，也能在与五六七八索相连后，形成宝牌雀头。一筒摸三筒，则能构成一三四赤五五六筒的两面嵌张复合形。逐项排除后，九万最不需要。"],"discard":"9m","shanten":3,"comparisons":[],"terms":[],"action":"discard"},{"id":115,"question_pdf":94,"answer_pdf":95,"question_printed":89,"answer_printed":90,"hand":["3m","4m","5m","6m","6m","7m","3p","3p","7p","7p","1s","3s","5s"],"draw":"6s","meta_ocr":"4巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora115.webp","translation":["为了固定三面进张而切六万，之后摸到宝牌三万就会难处理。依照五组理论拆掉弱嵌张，朝断幺九推进。"],"discard":"1s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":116,"question_pdf":94,"answer_pdf":95,"question_printed":89,"answer_printed":90,"hand":["4m","5m","6m","6m","6m","7m","3p","4p","5s","6s","6s","7s","8s"],"draw":"8s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora116.webp","translation":["不能因为四索是宝牌，就急着切八索；否则七万会成为无用牌。切七万不仅有效牌最多，摸七索还能形成一杯口。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":117,"question_pdf":94,"answer_pdf":95,"question_printed":89,"answer_printed":90,"hand":["3m","7m","8m","9m","2p","3p","4p","5p","5p","6p","1s","2s","3s"],"draw":"4s","meta_ocr":"东1局 東家 7巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora117.webp","translation":["切三万、六筒、一索的进张几乎相同。这手牌可看作以宝牌五筒为雀头、等待三万、六筒、四索靠张听牌。对这种形来说，半吊子的连续形比独立浮牌更容易导致和牌枚数减少。留下独立三万，靠张至少有4枚和牌张，另有三色与赤牌进张；留下六筒可期待多面听，也有摸二筒等非直接靠张变化。逐项排除，四索最不需要，因此切一索。很多人可能为了最差时保留索子延边而留一索，但真正必须保留这类延边的情况不多。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":118,"question_pdf":96,"answer_pdf":97,"question_printed":91,"answer_printed":92,"hand":["3m","4m","4m","4m","5p","6p","7p","3s","4s","6s","7s","9s","9s"],"draw":"9s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora118.webp","translation":["索子的进张重叠，切六索后能同时保留七索与八索进张，因此最宽，也更容易留下好形听牌。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":119,"question_pdf":96,"answer_pdf":97,"question_printed":91,"answer_printed":92,"hand":["2m","3m","4m","6m","7m","7m","2p","3p","3p","4p","6s","7s","8s"],"draw":"9s","meta_ocr":"東1局 東家 4巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora119.webp","translation":["单看有效牌，切三筒最多；但二三三四筒这种中膨形，只要靠张就一定能取两面听。在平和一向听中保留它，非常有利。相比之下，索子靠近边端，靠张功能较弱。切九索也更容易形成断幺九，提高打点；摸五万或七万，还可能出现三面听。"],"discard":"9s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":120,"question_pdf":96,"answer_pdf":97,"question_printed":91,"answer_printed":92,"hand":["2m","3m","4m","6m","7m","7m","2p","3p","4p","4p","6s","7s","8s"],"draw":"0s","meta_ocr":"东1局 東家 4巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora120.webp","translation":["宝牌六万，切七万、固定宝牌似乎不错，但进张过窄；切宝牌六万虽然最宽，这个形又实在不值得这么做。综合平衡，切四筒正确。摸五万至八万、四索至九索，都能做成打点足够的手。尤其在带祝仪的规则中，有赤1就应视为足够，基本原则是瞄准容易自摸和牌的最终形。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":121,"question_pdf":98,"answer_pdf":99,"question_printed":93,"answer_printed":94,"hand":["1m","2m","2m","3m","4m","6m","5p","7p","7p","3s","4s","7s","8s"],"draw":"9s","meta_ocr":"束1局 束家 巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora121.webp","translation":["万子是在两面嵌张复合形边上又连了一张的结构，可进三万与五万。直接保留一向听即可。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":122,"question_pdf":98,"answer_pdf":99,"question_printed":93,"answer_printed":94,"hand":["2m","3m","4m","5m","6m","3p","4p","4p","5p","6p","3s","3s","0s"],"draw":"6s","meta_ocr":"东1局 東家 5巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora122.webp","translation":["直接选择有效牌最多的切法。庄家已有赤1，还贪心地拆万子，是严重失误。之后摸七筒，再与万子交换即可。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":123,"question_pdf":98,"answer_pdf":99,"question_printed":93,"answer_printed":94,"hand":["2m","3m","3m","5m","6m","7m","8m","4p","4p","4p","6p","0s","6s"],"draw":"7s","meta_ocr":"东1局 73 巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora123.webp","translation":["有三色与赤牌进张，不考虑切六筒。实际比较二万与八万。若五筒先进入，应像原书补充牌例那样，取高目567三色的变则三面听。因此无需再考虑一四万最终形，一开始就固定三万雀头，保留万子四连形与六筒靠张更好。两面听牌就会立即立直，因此不会再发展成一气通贯。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":124,"question_pdf":100,"answer_pdf":101,"question_printed":95,"answer_printed":96,"hand":["3m","5m","3p","4p","6p","7p","8p","3s","4s","4s","5s","5s","5s"],"draw":"0s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora124.webp","translation":["索子可分成三四赤五索，以及四五五五索来理解。单看进张，切四索最宽；但重视最终形，应拆万子。为保留摸赤五万的机会，切三万正确。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":125,"question_pdf":100,"answer_pdf":101,"question_printed":95,"answer_printed":96,"hand":["3m","3m","4m","4m","5m","6m","7m","8m","8m","4p","6p","4s","5s"],"draw":"5p","meta_ocr":"束1局 東家 8巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora125.webp","translation":["切八万最宽，但若万子先补入，有可能留下单骑听。切四万既尽量确保用上宝牌，又保留较宽进张，因此正确。即使摸到看似反向的九万，也能取高目三色，这点价值很大。"],"discard":"4m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":126,"question_pdf":100,"answer_pdf":101,"question_printed":95,"answer_printed":96,"hand":["6m","7m","6p","7p","4s","4s","0s","6s","7s","7s","8s","8s","9s"],"draw":"9s","meta_ocr":"东1局 東家 8巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora126.webp","translation":["比起尚不确定的三色，更应确保一杯口。虽然暂时没有雀头，但一杯口这个役已经确定，之后即便形成单骑听也无妨。即使维持当前结构，摸六万、七万、六筒、七筒重成对子，共四种12枚，也能形成两面听。按简单计算，约有43%的听牌进张能形成门前平和一杯口赤1立直。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":127,"question_pdf":102,"answer_pdf":103,"question_printed":97,"answer_printed":98,"hand":["1m","2m","2m","3m","4m","7m","8m","1p","2p","3p","4p","6p","7s"],"draw":"8s","meta_ocr":"4巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora127.webp","translation":["能看到平和的两向听，应保留容易形成雀头的结构。切六筒后，不仅摸二万、五万，摸一万、四万、一筒、四筒重成对子，也都能形成雀头。"],"discard":"6p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":128,"question_pdf":102,"answer_pdf":103,"question_printed":97,"answer_printed":98,"hand":["6m","7m","5p","6p","7p","2s","3s","4s","5s","6s","6s","7s","8s"],"draw":"5p","meta_ocr":"束1局 7巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora128.webp","translation":["切五筒单看进张最多，但摸一索、四索、七索后会留下单骑听，断幺九也容易被破坏。切六索兼顾三色、断幺九、赤牌与确定的好形，期望值最高。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":129,"question_pdf":102,"answer_pdf":103,"question_printed":97,"answer_printed":98,"hand":["7m","8m","2p","3p","6p","7p","7p","2s","3s","3s","3s","4s","6s"],"draw":"7s","meta_ocr":"东1局 東家 4巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora129.webp","translation":["若把二二三三四索看成两组，目前共有六组，很多人可能会拆二三筒。但三索与七筒各只剩1枚，七筒还是宝牌指示牌；即使拆二三筒，保留的五组功能也不好。这里先拆一枚七筒，固定可进宝牌的搭子，刻意按六组推进，反而更快、打点也更强。提前打掉危险的宝牌指示牌，也是优点。"],"discard":"7p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":130,"question_pdf":104,"answer_pdf":105,"question_printed":99,"answer_printed":100,"hand":["5m","5m","5m","6m","7m","7m","3p","4p","5p","6p","7s","8s","8s"],"draw":"1p","meta_ocr":"8巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora130.webp","translation":["直接切七万，保留最大进张。自己是庄家，即使最后听嵌二筒，也应毫不犹豫地立即立直。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":131,"question_pdf":104,"answer_pdf":105,"question_printed":99,"answer_printed":100,"hand":["6m","7m","1s","1s","2s","4s","4s","5s","6s","6s","7s","4z","4z"],"draw":"0m","meta_ocr":"東1局 東家 9巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora131.webp","translation":["进张较宽，摸三索形成平和是最高形，与北组成双碰听也不差。乍看似乎切四索的两面嵌张形偏重宽度，而切二索的一杯口形偏重打点；但切四索还可能有平和，因此宽度与打点两方面都更有利。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":132,"question_pdf":104,"answer_pdf":105,"question_printed":99,"answer_printed":100,"hand":["1m","1m","1m","2m","3m","4m","5m","2p","3p","1s","1s","1s","2s"],"draw":"1s","meta_ocr":"东1局 東家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora132.webp","translation":["这是俗称“增加1番”的手牌，幺九牌或字牌的暗杠，大致相当于增加1番。听牌进张有二万、五万、三万、六万、一筒、四筒、二索，预计很快就能听牌。既然完全是进攻手，实战中应立即暗杠一索，听牌后立即立直。也可先切二索，摸到有效牌后再杠，但与立即杠相比，会少3枚有效牌。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"kan"},{"id":133,"question_pdf":106,"answer_pdf":107,"question_printed":101,"answer_printed":102,"hand":["1m","1m","3m","5m","3p","4p","6p","7p","4s","4s","6s","2z","2z"],"draw":"8p","meta_ocr":"5巡目 束1月 南家","banner_y":339,"original_only":false,"round":"东1局","seat":"南家","turn":5,"special":"","dora_image":"images/dora133.webp","translation":["虽然有三个雀头候选，但其中有役牌对子，应以鸣牌为前提，保留容易碰的牌。依照“弱搭子用三张组成”的理论，把万子保留为三张才正确。"],"discard":"5m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":134,"question_pdf":106,"answer_pdf":107,"question_printed":101,"answer_printed":102,"hand":["4m","5m","6m","6m","6m","7m","3p","4p","5s","6s","6s","7s","8s"],"draw":"8s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora134.webp","translation":["既取最大进张，又期待摸入宝牌五万。若错过赤五万，会很懊悔。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":135,"question_pdf":106,"answer_pdf":107,"question_printed":101,"answer_printed":102,"hand":["5m","6m","7m","7m","8m","8m","9m","4s","4s","4s","0s","7s","7s"],"draw":"8s","meta_ocr":"东1局 東家 7巡目","banner_y":1198,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora135.webp","translation":["单看进张，切赤五索或八索明显更宽，但赤五索难以用上。于是容易想到拆八万，可那又无法应对摸宝牌五万。正确做法是切七索，既准备宝牌五万，也期待索子好形。四四四赤五七八索看似因六索重复进张而不够好，其实仅三索与五索就有7枚进张，已经很强；前进一步之后，至少两面以上的进张仍能保留。若没看出它是好形，应修正对牌形的认识。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":136,"question_pdf":108,"answer_pdf":109,"question_printed":103,"answer_printed":104,"hand":["7m","7m","9m","2p","3p","7p","8p","9p","2s","2s","0s","6s","7s"],"draw":"5m","meta_ocr":"4巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora136.webp","translation":["在七万与九万之间选择。切九万、保留两个雀头时，能体现两面变化优势的只有摸三索；此时保留两嵌形更容易形成平和。若一筒、四筒先进入，最终也会留下先切七万、再切五万后的嵌八万，这种舍牌顺序使等待更强。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":137,"question_pdf":108,"answer_pdf":109,"question_printed":103,"answer_printed":104,"hand":["3m","3m","4m","4p","4p","4p","2s","3s","4s","4s","5s","5s","6s"],"draw":"0p","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora137.webp","translation":["尽量不让赤五筒被迫打出，是有赤规则的基本原则。这手牌能看到345三色；若万子完成，就听筒子，若筒子完成，就听万子。沿着这个思路，应先完成索子的两个面子。切三万看似灵活，实际只是增加了最后不得不切赤五筒的进张。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":138,"question_pdf":108,"answer_pdf":109,"question_printed":103,"answer_printed":104,"hand":["4m","4m","6m","7m","8m","6p","7p","7p","1s","3s","3s","?","?"],"draw":"?","meta_ocr":"東1局 南家 7巡目","banner_y":1427,"original_only":true,"round":"东1局","seat":"南家","turn":7,"special":"","dora_image":"images/dora138.webp","translation":["为让最终形更容易成为好形，推荐固定两面。不要因为四万是宝牌，就贪心地把最终形做成含宝牌的双碰听，否则往往失败。即使局面必须满贯，也可先切七筒期待赤牌；随后索子有可鸣牌的机会，也尽可能先放过，等到最后再决定。要记住这种处理方式。"],"discard":"7p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":139,"question_pdf":110,"answer_pdf":111,"question_printed":105,"answer_printed":106,"hand":["4m","5m","7m","8m","2p","4p","4p","6p","8p","2s","3s","9s","9s"],"draw":"9m","meta_ocr":"4巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora139.webp","translation":["乍看违反“两雀头理论”，但按两个雀头推进，很可能变成无役、无宝牌听牌，而且后续变化少。所以这里应选择最容易形成平和的结构。切二筒与四筒，直接有效牌枚数并没有差别。"],"discard":"4p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":140,"question_pdf":110,"answer_pdf":111,"question_printed":105,"answer_printed":106,"hand":["4m","4m","8m","9m","3p","3p","7p","8p","9p","3s","4s","6s","6s"],"draw":"8s","meta_ocr":"東1局 西家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora140.webp","translation":["六组，搭子过多。依五组理论，应看远一步，保留更强的五组；这里拆最弱的八九万边张。考虑摸六万后，万子能形成四六八万两嵌形，先从九万细致地拆起。因为想做三色或筋引诱，就切四万，是不好的处理。"],"discard":"9m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":141,"question_pdf":110,"answer_pdf":111,"question_printed":105,"answer_printed":106,"hand":["2m","3m","4m","5m","5m","3p","4p","5p","3s","5s","6s","6s","7s"],"draw":"6m","meta_ocr":"东1局 東家 7巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora141.webp","translation":["虽能看到345三色，但可能留下嵌张听的三色，这里应放弃。单看进张是切六索，考虑最终形则切三索。这样大概率形成断幺平和，摸五索或九索可做高目一杯口，摸二万还可形成三面听。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":142,"question_pdf":112,"answer_pdf":113,"question_printed":107,"answer_printed":108,"hand":["5m","6m","7m","8m","3p","4p","5p","7p","7p","2s","3s","4s","4s"],"draw":"6p","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora142.webp","translation":["切四索在宽度和打点上都更出色。犹豫时，拆掉亚两面形，通常较接近正确答案。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":143,"question_pdf":112,"answer_pdf":113,"question_printed":107,"answer_printed":108,"hand":["6m","6m","6m","7m","4p","5p","6p","6p","6p","7p","7p","7p","8p"],"draw":"8m","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora143.webp","translation":["切八筒可取六九万、三六筒的变则四面听，但六万和牌时只有立直这一役。这里应切四筒、立即立直，确定庄家满贯；无论以五筒还是八筒和牌，都一定有一杯口。"],"discard":"4p","shanten":0,"comparisons":[],"terms":[],"action":"riichi"},{"id":144,"question_pdf":112,"answer_pdf":113,"question_printed":107,"answer_printed":108,"hand":["2m","3m","4m","2p","4p","6p","6p","7p","8p","1s","2s","3s","4s"],"draw":"0s","meta_ocr":"东1局 東家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora144.webp","translation":["这手牌能看到234三色，但切六筒会失去宝牌九筒进张；切一索追三色，除非固定赤五索雀头，否则会被迫打掉赤牌。在有赤规则中，234和678三色常因摸赤牌而被破坏，本题也是如此。直接切二筒，宽进张地瞄准门前平和正确。特别在祝仪规则中，有赤牌时更应形成容易自摸和牌的最终形。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":145,"question_pdf":114,"answer_pdf":115,"question_printed":109,"answer_printed":110,"hand":["6m","7m","9m","9m","2p","2p","3p","3p","4p","5p","6p","7p","7p"],"draw":"8p","meta_ocr":"9巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora145.webp","translation":["切二筒后，筒子成为左右对称的九张“翼形”，可进一筒、四筒、六筒、九筒。加上万子两面，共六种22枚，为最大进张，而且全部能形成平和听牌。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":146,"question_pdf":114,"answer_pdf":115,"question_printed":109,"answer_printed":110,"hand":["2m","3m","4m","3p","4p","4p","5p","6p","7p","7p","6s","7s","7s"],"draw":"8p","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora146.webp","translation":["筒子为八张翼形。切七索，形成“超完全一向听”，既能应对意外摸入的宝牌四筒，也保留全部赤牌进张。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":147,"question_pdf":114,"answer_pdf":115,"question_printed":109,"answer_printed":110,"hand":["1m","2m","3m","3p","4p","4p","5p","6p","7p","7p","2s","2s","3s"],"draw":"8p","meta_ocr":"东1局 東家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora147.webp","translation":["筒子为八张翼形。若只计算最终至少两面听的有效牌，切二索与三索同为26枚，优于其他切法。切二索是片山政幸漫画《打姬奥巴卡米科》（竹书房）所称的“超完全一向听”，可确保平和；但切三索后，摸三筒、六筒、五筒、八筒还能做高目一杯口，期望值更高。作者戏称它是“超完全一向听2”。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":148,"question_pdf":116,"answer_pdf":117,"question_printed":111,"answer_printed":112,"hand":["3m","4m","5m","6m","7m","3p","5p","7p","8p","1s","1s","9s","9s"],"draw":"4p","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora148.webp","translation":["面子候选已足够，为追求平和，应拆雀头。拆一索或九索看似相同，但已知两枚九索的位置，立直后里宝牌的期望值会有细小差别，因此切一索略有利。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":149,"question_pdf":116,"answer_pdf":117,"question_printed":111,"answer_printed":112,"hand":["1m","3m","5m","6m","7m","7m","9m","5p","6p","3s","3s","4s","6s"],"draw":"4m","meta_ocr":"東1局 東家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora149.webp","translation":["一气通贯很可能导致打出宝牌，应放弃。比较一万与九万，切九万的话，摸二万即可形成能确保用上宝牌的一向听。"],"discard":"9m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":150,"question_pdf":116,"answer_pdf":117,"question_printed":111,"answer_printed":112,"hand":["5m","5m","1p","2p","3p","2s","3s","3s","5s","5s","7s","8s","8s"],"draw":"6m","meta_ocr":"东1局 東家 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora150.webp","translation":["虽然有四个雀头候选，但现在只有五组，结构也好；没有其他场上信息时，应固定一个两面。若要保留摸赤五万，并尽量形成靠近边端的最终形，实际比较三索与八索。两者在内侧牌进入时有细小但确定的差别：保留三索，摸四索形成一向听后，还能在切六万与切三索之间选择。多数时候，把牌的结构固定清楚，后续更容易得到好形。本题应留下靠近赤五索对子的三索。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":151,"question_pdf":120,"answer_pdf":121,"question_printed":115,"answer_printed":116,"hand":["2p","2p","4p","4p","5p","6p","7p","1s","2s","2s","3s","4s","5s"],"draw":"6p","meta_ocr":"南4局 7巡目 南家","banner_y":339,"original_only":false,"round":"南4局","seat":"南家","turn":7,"special":"和牌即可取得第一名","dora_image":"images/dora151.webp","translation":["有效牌最多，能留下平和形，也可以碰听。摸三筒后再切六筒，还能变化成更好的好形一向听。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":152,"question_pdf":120,"answer_pdf":121,"question_printed":115,"answer_printed":116,"hand":["5m","6m","7m","8m","8m","3p","3p","4p","4p","4p","5p","6p","6s"],"draw":"7s","meta_ocr":"南4局 南家 5巡目","banner_y":798,"original_only":false,"round":"南4局","seat":"南家","turn":5,"special":"和牌即可取得第一名","dora_image":"images/dora152.webp","translation":["切三筒有效牌最多。不仅可以碰八万，也可以碰四筒。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":153,"question_pdf":120,"answer_pdf":121,"question_printed":115,"answer_printed":116,"hand":["5m","6m","7m","8m","8m","3p","3p","4p","4p","4p","5p","6p","5s"],"draw":"7s","meta_ocr":"南4局 南家 5巡目","banner_y":1198,"original_only":false,"round":"南4局","seat":"南家","turn":5,"special":"和牌即可取得第一名","dora_image":"images/dora153.webp","translation":["和牌即可取得第一名，不能只看进张宽度，应更重视鸣牌效率。八万、三筒、四筒可以碰，二筒、五筒、七筒可以吃。四筒应碰而非吃：形成四筒壁后，三筒可能更容易出现；摸七筒又能形成三面听。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":154,"question_pdf":122,"answer_pdf":123,"question_printed":117,"answer_printed":118,"hand":["2m","4m","6p","7p","6s","7s","8s","8s","?","?","?","?","?"],"draw":"?","meta_ocr":"南4局 7巡目 束家","banner_y":339,"original_only":true,"round":"南4局","seat":"东家","turn":7,"special":"和牌即可取得第一名","dora_image":"images/dora154.webp","translation":["只看听牌效率，切八索更宽；但考虑鸣牌后的实际和牌速度，应拆弱嵌张。这里重视危险度，推荐从内侧四万开始；实战则应留下更容易重成对子的那一张。"],"discard":"4m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":155,"question_pdf":122,"answer_pdf":123,"question_printed":117,"answer_printed":118,"hand":["7m","8m","9m","3p","5p","5p","4s","6s","7s","8s","7m","?","?"],"draw":"?","meta_ocr":"南4局 7巡目 南家","banner_y":855,"original_only":true,"round":"南4局","seat":"南家","turn":7,"special":"和牌即可取得第一名","dora_image":"images/dora155.webp","translation":["把嵌张鸣牌纳入考虑，就很容易判断：比较鸣牌后剩下的形是否为两面。八万和赤五索出现时一定要吃。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":156,"question_pdf":122,"answer_pdf":123,"question_printed":117,"answer_printed":118,"hand":["8m","8m","4p","4p","6p","3s","4s","6s","8s","8s","4z","4z","4z"],"draw":"7p","meta_ocr":"南4局 南家 4巡目","banner_y":1313,"original_only":false,"round":"南4局","seat":"南家","turn":4,"special":"和牌即可取得第一名","dora_image":"images/dora156.webp","translation":["和牌即可第一，这里应拆掉北暗刻，朝断幺九推进。其实当前共有六组，搭子过多，只用中张牌就足够保留面子候选。拆暗刻虽要多花三巡，但换来确定断幺九，所有搭子都可以鸣牌。若把吃看作两倍速度、碰看作四倍速度，这条路线反而更快。"],"discard":"4z","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":157,"question_pdf":124,"answer_pdf":125,"question_printed":119,"answer_printed":120,"hand":["1m","1m","1m","3p","4p","6p","8p","7s","8s","9s","9s","7z","7z"],"draw":"7z","meta_ocr":"南4局 7巡目 南家","banner_y":339,"original_only":false,"round":"南4局","seat":"南家","turn":7,"special":"和牌即可取得第一名","dora_image":"images/dora157.webp","translation":["考虑包括鸣牌在内的速度，拆掉较弱的嵌张。注意不能不小心从内侧六筒开始切，否则会失去摸三筒听牌的机会。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":158,"question_pdf":124,"answer_pdf":125,"question_printed":119,"answer_printed":120,"hand":["6m","6m","7m","7m","8m","2p","3p","3p","4p","5p","6p","6p","7p"],"draw":"7p","meta_ocr":"南4局 南家 9巡目","banner_y":855,"original_only":false,"round":"南4局","seat":"南家","turn":9,"special":"和牌即可取得第一名","dora_image":"images/dora158.webp","translation":["虽然很想追求二杯口，但这里和牌即可第一。切三筒，既保留最大进张，也保留六万、七万、六筒、七筒四种碰听机会。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":159,"question_pdf":124,"answer_pdf":125,"question_printed":119,"answer_printed":120,"hand":["6m","6m","2p","3p","4p","4p","4p","5p","5p","7s","8s","7z","7z"],"draw":"7z","meta_ocr":"南4局 南家 7巡目","banner_y":1369,"original_only":false,"round":"南4局","seat":"南家","turn":7,"special":"和牌即可取得第一名","dora_image":"images/dora159.webp","translation":["和牌即可第一，不需要一杯口或三暗刻。应保留容易从上家吃到的一筒、能吃听的形。切五筒进张最多；一筒、三筒、六筒、六索、九索可吃，六万、四筒可碰。特别注意，上家打四筒时也应碰而非吃，因为可应对赤五筒交换，也能利用四筒壁提高防守能力。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":160,"question_pdf":126,"answer_pdf":127,"question_printed":121,"answer_printed":122,"hand":["6m","6m","7m","8m","3p","4p","5p","4s","5s","6s","7s","4z","4z"],"draw":"4p","meta_ocr":"南4局 7巡目 西家","banner_y":339,"original_only":false,"round":"南4局","seat":"西家","turn":7,"special":"和牌即可取得第一名","dora_image":"images/dora160.webp","translation":["只看听牌枚数，切四筒有利；但为了更容易形成平和，推荐切六万。目前有效牌很多，拆北对子再转向断幺九，反而会变慢。"],"discard":"6m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":161,"question_pdf":126,"answer_pdf":127,"question_printed":121,"answer_printed":122,"hand":["2m","4m","6m","9m","9m","5p","7p","2s","4s","6s","8s","1z","5z"],"draw":"7z","meta_ocr":"南4局 東家 巡目","banner_y":798,"original_only":false,"round":"南4局","seat":"东家","turn":1,"special":"和牌即可取得第一名","dora_image":"images/dora161.webp","translation":["若先切役牌、按普通牌效率推进，很可能最终无役。和牌即可第一，就应从配牌开始想象最终形。这里兼顾断幺九与役牌，一口气拆掉九万对子。虽然暂时失去雀头，但此时役的确定性比牌效率更重要。"],"discard":"9m","shanten":4,"comparisons":[],"terms":[],"action":"discard"},{"id":162,"question_pdf":126,"answer_pdf":127,"question_printed":121,"answer_printed":122,"hand":["2m","2m","3m","6m","7m","8m","3p","4p","5p","8p","8p","4s","4s"],"draw":"6s","meta_ocr":"東1局 西家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora162.webp","translation":["若能碰到宝牌八筒就很简单，可这是一直碰不到、又已没有明显舍牌的形。三个雀头候选，切二万或四索拆对子的进张最多，但不能确定断幺九。若考虑食断，切三万或六索、维持三个雀头似乎不错，却很可能留下愚形听牌。各自都有优缺点、差别并不明确时，重视门前效率，兼顾立直、自摸和里宝牌，期望值更高。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":163,"question_pdf":128,"answer_pdf":129,"question_printed":123,"answer_printed":124,"hand":["3m","4m","4m","2p","4p","5p","6p","6p","7p","7p","8p","7s","8s"],"draw":"8s","meta_ocr":"5巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora163.webp","translation":["摸嵌三筒便能形成断幺平和听牌。提前处理之后危险的宝牌指示牌，固定宝牌进张，再期待筒子与索子变化。"],"discard":"4m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":164,"question_pdf":128,"answer_pdf":129,"question_printed":123,"answer_printed":124,"hand":["2m","2m","3m","3m","4m","0m","6m","8m","7p","8p","6s","7s","8s"],"draw":"6m","meta_ocr":"東1局 東家 6巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora164.webp","translation":["切八万的进张最多；但切二万，万子就成为可进一万、四万、七万的两面嵌张变形，摸七万可取高目平和三色。因为已有赤五万，无论怎样都不会形成一杯口。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":165,"question_pdf":128,"answer_pdf":129,"question_printed":123,"answer_printed":124,"hand":["1m","2m","2m","6m","8m","8m","4p","6p","6p","2s","3s","7s","8s"],"draw":"6s","meta_ocr":"东1局 東家 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora165.webp","translation":["三个雀头候选，依“三雀头最弱理论”，维持三个雀头会使当前进张少2枚。但拆对子取最大进张，例如切六筒，在一向听时若两个雀头结构再被破坏，容易产生多余牌，使进张宽度反而被追上。本题门前推进似乎耗时较长，因此先向内整理，也观察食断路线。"],"discard":"1m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":166,"question_pdf":130,"answer_pdf":131,"question_printed":125,"answer_printed":126,"hand":["1m","1m","3m","6m","7m","4p","4p","6p","3s","4s","6s","6s","8s"],"draw":"0m","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora166.webp","translation":["从三个雀头候选先向内整理。这样当前进张最多，向断幺九转移也顺畅；万一上家早早打出赤牌，也可以吃。"],"discard":"1m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":167,"question_pdf":130,"answer_pdf":131,"question_printed":125,"answer_printed":126,"hand":["2m","4m","6m","1p","2p","3p","2s","2s","3s","3s","4s","5s","5s"],"draw":"5s","meta_ocr":"東1局 西家 6巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora167.webp","translation":["单看进张，切二索最多；能一眼看出来很不容易。切二索也可兼顾234三色。不过这里切二万，观察一杯口、摸宝牌，以及摸七万向两面变化，综合期望值更高。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":168,"question_pdf":130,"answer_pdf":131,"question_printed":125,"answer_printed":126,"hand":["1m","2m","3m","7m","8m","1p","3p","3p","1s","2s","2s","6s","8s"],"draw":"8s","meta_ocr":"东1局 西家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora168.webp","translation":["三色的路线已经如此清楚，切三筒就是正确选择。切六索看似既保留三色，也留下后续厚度，但这些“厚度”对应的变化都会破坏三色。切三筒当前进张最多，除了赤五索与七索，也能应对四筒；最终即使听嵌二筒，也更强。切二索被切三筒全面涵盖，切一索则被切一筒全面涵盖。"],"discard":"3p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":169,"question_pdf":132,"answer_pdf":133,"question_printed":127,"answer_printed":128,"hand":["2m","3m","7m","8m","8m","8m","2p","3p","4p","1s","2s","3s","4s"],"draw":"5p","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora169.webp","translation":["过去这手牌会推荐切七万，兼顾123与234三色；但有赤规则下，应直接切一索，保留最大进张。这样仍能留下234三色。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":170,"question_pdf":132,"answer_pdf":133,"question_printed":127,"answer_printed":128,"hand":["2m","3m","4m","9m","9m","4p","6p","6p","2s","4s","4s","5s","6s"],"draw":"7s","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora170.webp","translation":["九万是宝牌，应按门前推进。依“三雀头最弱理论”，此时拆对子能使当前进张最大。筒子有两种向两面变化的机会，索子有三种，所以拆索子对子。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":171,"question_pdf":132,"answer_pdf":133,"question_printed":127,"answer_printed":128,"hand":["3m","5m","8m","8m","9p","9p","4s","5s","6s","7s","9s","6z","6z"],"draw":"6z","meta_ocr":"東1局 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"北家","turn":5,"special":"","dora_image":"images/dora171.webp","translation":["虽有三个雀头候选，但宝牌役牌已经是暗刻，应保留其他对子以便碰听。于是比较三五万与七九索。完整保留索子连续形，不仅能向两面变化，也更善于利用四索、六索、九索重成对子。仅看两面变化而拆九索，摸八万、九筒时会形成嵌四万听，后续变化少。三五万之间，为期待靠近边端的两面变化，先切五万。"],"discard":"5m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":172,"question_pdf":134,"answer_pdf":135,"question_printed":129,"answer_printed":130,"hand":["2m","3m","4m","6m","6m","7m","6p","4s","4s","5s","6s","7s","8s"],"draw":"5m","meta_ocr":"9巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora172.webp","translation":["要利用索子三面进张，需要雀头；但切四索后的结构不容易形成雀头。不如固定四索雀头，等待靠张听牌，兼顾含宝牌的三色。这样也能应对全部三种赤牌。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":173,"question_pdf":134,"answer_pdf":135,"question_printed":129,"answer_printed":130,"hand":["3p","5p","5p","6p","7p","0s","5s","6s","7s","7s","7s","8s","8s"],"draw":"0p","meta_ocr":"束1局 南家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"南家","turn":7,"special":"","dora_image":"images/dora173.webp","translation":["切掉宝牌三筒，形确实最好；但只要能用上这枚宝牌，鸣牌也能满贯。3900与8000差距很大，应尽量保留。切五索虽可能留下愚形，实际上有效牌最多，也有高打点潜力；意外再摸三筒，也不会难处理。"],"discard":"5s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":174,"question_pdf":134,"answer_pdf":135,"question_printed":129,"answer_printed":130,"hand":["2m","3m","3m","1p","3p","3p","7p","2s","3s","4s","8s","4z","4z"],"draw":"2p","meta_ocr":"东1局 東家 3巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora174.webp","translation":["单看进张，切三万有利；但搭子不足，不必急着固定含宝牌搭子。宝牌重成对子、摸四万等，都会带来高打点变化。三万多数时候终归要切，但如果最终能利用两枚，回报很大。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":175,"question_pdf":136,"answer_pdf":137,"question_printed":131,"answer_printed":132,"hand":["2m","2m","3m","7m","8m","5s","6s","6s","7s","7s","7s","9s","9s"],"draw":"6m","meta_ocr":"束1月 束家 6巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora175.webp","translation":["与其依赖断幺九绕远路，切二万已有24枚进张，直接取最大进张即可。即使最终切掉宝牌七索，打点仍足够。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":176,"question_pdf":136,"answer_pdf":137,"question_printed":131,"answer_printed":132,"hand":["2m","2m","2m","3m","4m","7m","8m","5p","6p","2s","3s","5s","5s"],"draw":"5m","meta_ocr":"束1局 7巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora176.webp","translation":["搭子过多，已有宝牌3，应以鸣牌为前提、向内整理。在不能确定断幺九的七八万与二三索之间，切二索后，即便摸到反向的四索，也可再切五索，转成更宽的一向听。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":177,"question_pdf":136,"answer_pdf":137,"question_printed":131,"answer_printed":132,"hand":["1m","2m","3m","2p","3p","2s","2s","3s","3s","4s","5s","6s","6s"],"draw":"3p","meta_ocr":"東1局 西家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora177.webp","translation":["索子是含一杯口的特殊连续形。切五索取完全一向听看似不错，但切三筒不仅比它更宽，意外摸到宝牌二索时也能听牌。只看当前进张，切六索最多；不过筒子先完成时，会留下双碰听。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":178,"question_pdf":138,"answer_pdf":139,"question_printed":133,"answer_printed":134,"hand":["3m","4m","2p","2p","5p","6p","6p","7p","3s","3s","0s","6s","6s"],"draw":"7s","meta_ocr":"束1月 9巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":9,"special":"","dora_image":"images/dora178.webp","translation":["已经第9巡，拆对子退回两向听太慢。切六筒或六索，取一向听中的最大进张。两者乍看相同，但切六索后，摸四索或八索也能连接起来，更容易完成面子。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":179,"question_pdf":138,"answer_pdf":139,"question_printed":133,"answer_printed":134,"hand":["5m","6m","1p","1p","4p","5p","5p","6p","1s","1s","5s","6s","6s"],"draw":"7s","meta_ocr":"東1局 西家 3巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":3,"special":"","dora_image":"images/dora179.webp","translation":["这是看再下一步变化的“两阶段牌效率”。仍在序盘，应拆对子，瞄准门前平和三色。拆哪一个对子看似相同，但切一筒后摸三筒，可组成一三四五五六筒的两面嵌张复合形。"],"discard":"1p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":180,"question_pdf":138,"answer_pdf":139,"question_printed":133,"answer_printed":134,"hand":["4m","0m","5m","7m","3p","6p","6p","7p","8p","8p","2s","3s","4s"],"draw":"5p","meta_ocr":"东1局 西家 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora180.webp","translation":["比较七万与三筒，要看各自内侧牌进入时的区别。切七万后摸四筒会留下嵌张；切三筒后摸六万则可取两面。通常从四赤五五七万切七万，但要掌握更高一层的例外，才能继续提高。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":181,"question_pdf":142,"answer_pdf":143,"question_printed":137,"answer_printed":138,"hand":["5m","7m","9m","1p","1p","2p","2p","6p","7p","4s","4s","5s","6s"],"draw":"4m","meta_ocr":"束1局 西家 3巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":3,"special":"","dora_image":"images/dora181.webp","translation":["现在有六组，希望转向食断。七九万嵌张以后大概率会被拆掉，但若直接摸八万，就能形成门前平和一向听，所以先拆一筒。"],"discard":"1p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":182,"question_pdf":142,"answer_pdf":143,"question_printed":137,"answer_printed":138,"hand":["4m","4m","5m","4p","5p","6p","4s","4s","5s","5s","6s","7s","7s"],"draw":"4s","meta_ocr":"束1局 東家 4 巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora182.webp","translation":["牌形取自片山政幸漫画《满潮！自摸海流》（竹书房）。虽然是庄家，但好形变化多，还能做三色，值得拆听。重视宽度可切七索，重视三色切四万，重视一杯口切四索；综合宽度与打点，切四万较好。"],"discard":"4m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":183,"question_pdf":142,"answer_pdf":143,"question_printed":137,"answer_printed":138,"hand":["2m","3m","6m","8m","2p","3p","4p","4p","6p","7s","9s","7z","7z"],"draw":"1p","meta_ocr":"東1局 4巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora183.webp","translation":["含役牌的六组形，应依五组理论保留强的五组，不要因为可以碰中，就半途而废地切六筒。实际比较六八万与七九索。门前听牌后很可能立即立直，因此应留下作为最终听牌时更容易荣和的一组。"],"discard":"8m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":184,"question_pdf":144,"answer_pdf":145,"question_printed":139,"answer_printed":140,"hand":["6m","7m","3p","4p","6p","7p","8p","1s","2s","3s","3s","?","?"],"draw":"?","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":true,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora184.webp","translation":["鸣牌手的两面加两面形。若切四索、固定面子，吃牌后会留下单骑听。把吃听视为两倍速度，基本应在这里确定保留两个两面。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":185,"question_pdf":144,"answer_pdf":145,"question_printed":139,"answer_printed":140,"hand":["7m","8m","9m","1p","3p","5p","6p","8p","9p","3s","3s","0s","5s"],"draw":"6s","meta_ocr":"束1局 東家 3巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora185.webp","translation":["比较一筒与九筒。先切九筒，筒子保留二筒、四筒、七筒进张：摸四筒后形成仍能进二筒、七筒的分离两嵌形；摸七筒后形成进二筒、四筒的两嵌形。这是常见形，值得记住。"],"discard":"9p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":186,"question_pdf":144,"answer_pdf":145,"question_printed":139,"answer_printed":140,"hand":["3m","4m","4m","6m","8m","2p","3p","4p","7p","8p","8p","9p","9p"],"draw":"5p","meta_ocr":"东1局 西家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora186.webp","translation":["若一定维持一向听，应切三万；但它要求门前推进，最终又容易是愚形，条件苛刻。这里放弃一杯口，瞄准一气通贯或食断。单看形容易想拆八筒，但多数筒子进张最后都会把九筒挤出去，不如现在就切九筒；尤其摸六筒后的形很强。"],"discard":"9p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":187,"question_pdf":146,"answer_pdf":147,"question_printed":141,"answer_printed":142,"hand":["3m","3m","2p","3p","4p","5p","8p","9p","3s","4s","7s","8s","9s"],"draw":"8p","meta_ocr":"8巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":8,"special":"","dora_image":"images/dora187.webp","translation":["选择一向听中的最大进张。切五筒，也是在为之后的双碰听保留诱导他家放铳的舍牌。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":188,"question_pdf":146,"answer_pdf":147,"question_printed":141,"answer_printed":142,"hand":["3m","5m","7m","4p","0p","6p","3s","5s","5s","6s","6s","7s","8s"],"draw":"4m","meta_ocr":"束1局 7巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora188.webp","translation":["切六索的进张最多，但考虑最终形，切三索更有利。这两种切法的枚数远高于其他候选，是因为三索与六索的进张存在筋上的重叠。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":189,"question_pdf":146,"answer_pdf":147,"question_printed":141,"answer_printed":142,"hand":["3m","4m","4m","5m","6m","1p","1p","2p","3p","6s","6s","7s","8s"],"draw":"8s","meta_ocr":"東1局 西家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora189.webp","translation":["七索是宝牌指示牌，这个形不太舒服，但切一筒的进张优势仍大于拆索子。不过最后很容易听嵌七索，且七索正是指示牌，因此虽然听牌概率相差很多，最终和牌概率却没有那么大的差距。"],"discard":"1p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":190,"question_pdf":148,"answer_pdf":149,"question_printed":143,"answer_printed":144,"hand":["2m","3m","6m","7m","5p","5p","6p","7p","6s","6s","7s","7s","8s"],"draw":"8m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora190.webp","translation":["三色虽被破坏，但有效牌枚数与其他切法差距过大。无论哪种进张，都能形成包含宝牌八万、已有役的听牌，已经足够。若摸八筒，仍有三色机会。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":191,"question_pdf":148,"answer_pdf":149,"question_printed":143,"answer_printed":144,"hand":["2m","2m","4p","5p","2s","3s","4s","4s","5s","6s","7s","7s","8s"],"draw":"1s","meta_ocr":"束1局 7巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora191.webp","translation":["切一索、四索、七索，得到的一向听看似相似，但切一索会失去一气通贯。再比较四索与七索：切四索后摸三索，会失去断幺九。切七索能同时兼顾一气通贯与断幺九，因此正确。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":192,"question_pdf":148,"answer_pdf":149,"question_printed":143,"answer_printed":144,"hand":["4m","5m","7m","8m","6p","7p","8p","5s","6s","7s","7s","8s","9s"],"draw":"6m","meta_ocr":"东1局 西家 5巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora192.webp","translation":["变化多，还能追求断幺平和和三色的高打点，推荐拆听。实际比较七索与九索，进张数相同；三色完成率切九索仅多1枚，但断幺九的容易程度差别很大。切九索后，摸五索或六索形成含三色的听牌，可以在“默听高目满贯”与“立直高目跳满”之间选择。"],"discard":"9s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":193,"question_pdf":150,"answer_pdf":151,"question_printed":145,"answer_printed":146,"hand":["6m","6m","7m","2p","2p","4p","4p","5p","6p","6p","2s","3s","4s"],"draw":"7p","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora193.webp","translation":["有一杯口，容易想切六万；但从六万开始，摸二筒或四筒时，会被迫打掉宝牌六筒。因此应固定含宝牌的搭子。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":194,"question_pdf":150,"answer_pdf":151,"question_printed":145,"answer_printed":146,"hand":["4m","6m","6m","3p","3p","5p","7p","7p","8p","9p","5s","5s","7s"],"draw":"8p","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora194.webp","translation":["关键是发现这手牌处于七对子一向听。虽然也观察普通面子手，但那条路线满是嵌张，宜以七对子为主。兼顾赤牌进张、逐项排除后，切七索较好。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":195,"question_pdf":150,"answer_pdf":151,"question_printed":145,"answer_printed":146,"hand":["2m","4m","6m","8m","2p","2p","8p","8p","2s","4s","4s","0s","6s"],"draw":"7m","meta_ocr":"东1局 西家 4巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora195.webp","translation":["在二万、二筒、八筒、二索之间选择。依两雀头理论，应成组保留能利用重成对子、且摸内侧牌可形成两面的对子。因此该拆万子或索子的嵌张。万子摸内侧五万虽能三面听，摸九万却破坏断幺九，略显微妙；索子不仅摸五索很强，摸四索、六索、七索也能增加厚度。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":196,"question_pdf":152,"answer_pdf":153,"question_printed":147,"answer_printed":148,"hand":["3m","4m","5m","6m","7m","7m","3p","4p","4p","5p","6p","8p","3s"],"draw":"5s","meta_ocr":"6巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora196.webp","translation":["不要漏看：不只是摸五筒，摸七筒也能完成三色。"],"discard":"6m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":197,"question_pdf":152,"answer_pdf":153,"question_printed":147,"answer_printed":148,"hand":["2m","3m","4m","6m","7m","7m","3p","3p","4p","5p","6s","7s","8s"],"draw":"8s","meta_ocr":"束1局 東家 4巡目","banner_y":740,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora197.webp","translation":["切八索最容易形成好形听牌，和牌率与期望值都最高。已有宝牌1，即使摸一筒后听嵌张，也可以立直。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":198,"question_pdf":152,"answer_pdf":153,"question_printed":147,"answer_printed":148,"hand":["6p","6p","7p","8p","9p","3s","5s","6s","7s","7s","7s","7z","7z"],"draw":"2s","meta_ocr":"东1局 東家 8巡目","banner_y":1198,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora198.webp","translation":["当前有六组，搭子过多，基本原则是先保留强的五组。虽然无论怎样切，只要碰到宝牌中，似乎就能和牌，但已经第8巡，也要考虑碰不到的情况。索子无论进张还是最终形都很强，不拆。如果赤五筒还没出现，六六七八九筒应保留六七八面子，也就是从六筒与九筒开始拆。考虑危险度，先切六筒。"],"discard":"6p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":199,"question_pdf":154,"answer_pdf":155,"question_printed":149,"answer_printed":150,"hand":["2p","2p","2p","3p","5p","7p","1s","2s","3s","5s","6s","7s","8s"],"draw":"1p","meta_ocr":"6巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora199.webp","translation":["变化很多，应拆听。切五筒，兼顾一气通贯与宝牌进张。无宝牌的嵌张听立即立直，作者比喻为“通向地狱的单程票”，这里应避免。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":200,"question_pdf":154,"answer_pdf":155,"question_printed":149,"answer_printed":150,"hand":["2m","4m","6m","8m","8m","8m","3p","4p","0p","6p","7p","2s","3s"],"draw":"4s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora200.webp","translation":["庄家第7巡，至少断幺九宝牌2已经确定。比起三色，应优先考虑进张宽度与最终形。筒子形很好，也使三色最终完成的概率不高；因此万子应保留六八八八万的变则双面进张。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":201,"question_pdf":154,"answer_pdf":155,"question_printed":149,"answer_printed":150,"hand":["2m","4m","7m","8m","2p","4p","9p","9p","9p","1s","1s","4s","4s"],"draw":"6m","meta_ocr":"东1局 東家 3巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora201.webp","translation":["搭子过多，依五组理论拆掉最弱的一组。四索对子有两种两面变化，是强组；一索在四索对子转为两面后，要作雀头使用，应成组保留，这就是两雀头理论。剩下比较三四万与二四筒：三四万摸五万还能变成三面听，稍强。因此从外侧二筒开始，拆掉最弱的二四筒。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":202,"question_pdf":156,"answer_pdf":157,"question_printed":151,"answer_printed":152,"hand":["3m","3m","5m","5m","5m","2p","3p","3p","4p","2s","2s","6s","7s"],"draw":"1p","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora202.webp","translation":["“竟然找到了提高打点的种子！”比较三万与二索，切二索后，摸四万时还可以附加平和。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":203,"question_pdf":156,"answer_pdf":157,"question_printed":151,"answer_printed":152,"hand":["2m","3m","3m","4m","7m","3p","1s","2s","2s","3s","3s","8s","9s"],"draw":"9s","meta_ocr":"東1局 東家 3巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora203.webp","translation":["已有三个面子，也有雀头，关键是让最后一个面子从哪里靠张产生。应瞄准三万、七万、三筒的靠张，这是道基础题。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":204,"question_pdf":156,"answer_pdf":157,"question_printed":151,"answer_printed":152,"hand":["3m","4m","2p","3p","3p","4p","5p","6p","6p","7p","2s","2s","3s"],"draw":"4m","meta_ocr":"东1局 西家 5巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora204.webp","translation":["能追求234三色，宝牌是五筒。切三筒既保留三色，也充分利用五筒进张，进张数与期望值都最高。切四万也灵活，但摸三万、三色被破坏时，形不如切三筒；后者若摸五万，可切四索形成极好的一向听。解这道难题的诀窍是：瞄准完全一向听，宜维持两个雀头；为利用五筒，应考察周边牌。若把五六六七筒看成中膨形，就能想到拆六筒的筋牌三筒，再核验即可。"],"discard":"3p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":205,"question_pdf":158,"answer_pdf":159,"question_printed":153,"answer_printed":154,"hand":["0m","6m","7m","1p","1p","2p","3p","5p","6p","7p","7p","2s","4s"],"draw":"4s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora205.webp","translation":["四筒的进张重叠，因此切一筒有效牌最多。不必追求最终会留下嵌张或边张听的一杯口。"],"discard":"1p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":206,"question_pdf":158,"answer_pdf":159,"question_printed":153,"answer_printed":154,"hand":["4p","4p","4p","5p","7p","9p","9p","4s","5s","7s","9s","7z","7z"],"draw":"6s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora206.webp","translation":["筒子乍看复杂，只要想象碰中之后的结构，就应能马上判断。若筒子先补完，即使听嵌八索，也可以实战性地立即立直。无论用两雀头理论，还是弱搭子三张组成理论，都能得出切五筒。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":207,"question_pdf":158,"answer_pdf":159,"question_printed":153,"answer_printed":154,"hand":["3p","4p","6p","7p","1s","1s","2s","3s","7s","8s","8s","9s","9s"],"draw":"5p","meta_ocr":"东1局 西家 5巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora207.webp","translation":["雀头不明确的这种形，通常拆亚两面、切一索即可，但本题不同：筒子有三面进张，正中又是宝牌，应最大程度利用。切八索能确定平和，最终很可能为三面听。虽然当前枚数少于切一索，和牌率却最高，预期打点也不同，因此综合期望值最高。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":208,"question_pdf":160,"answer_pdf":161,"question_printed":155,"answer_printed":156,"hand":["2m","3m","7m","7m","8m","3p","4p","1s","2s","3s","5s","7s","9s"],"draw":"6s","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora208.webp","translation":["好形一向听，比较八万与九索。索子还存在一气通贯，因此从八万开始切。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":209,"question_pdf":160,"answer_pdf":161,"question_printed":155,"answer_printed":156,"hand":["2m","3m","6m","7m","7m","3p","4p","1s","2s","3s","5s","7s","9s"],"draw":"6s","meta_ocr":"東1局 東家 5巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora209.webp","translation":["面子候选足够，切六万、保留一气通贯也没问题；但推荐为赤五万保留变化，切九索。这样意外摸入宝牌三万，也可更换雀头。实战中，何时换入安全牌，也体现水平。"],"discard":"9s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":210,"question_pdf":160,"answer_pdf":161,"question_printed":155,"answer_printed":156,"hand":["4m","0m","6m","7m","5p","2s","4s","0s","5s","6s","6s","6s","8s"],"draw":"0p","meta_ocr":"东1局 南家 3巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"南家","turn":3,"special":"","dora_image":"images/dora210.webp","translation":["若连愚形都可以、只追求最快听牌，应切七万；但现在巡目早，想拆二索或八索，期待万子延伸。比较两者：切二索后摸九索，可取两面听；切八索后摸三索，只能取双碰听。此外，切二索后摸三索，可以再切八索，虽有振听，却变成宽进张一向听；反过来切八索后摸九索，则是纯粹的反向损失。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":211,"question_pdf":164,"answer_pdf":165,"question_printed":159,"answer_printed":160,"hand":["2m","4m","1p","1p","6p","7p","1s","2s","3s","5s","6s","8s","8s"],"draw":"9s","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora211.webp","translation":["现在两向听且搭子过多。依“一向听峰值理论”，目标应是含一气通贯、进张厚实的一向听。"],"discard":"2m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":212,"question_pdf":164,"answer_pdf":165,"question_printed":159,"answer_printed":160,"hand":["3m","3m","4m","5m","6m","8m","9m","5p","6p","6p","7p","2s","4s"],"draw":"3m","meta_ocr":"東1局 西家 4巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora212.webp","translation":["只要能想象二三三三四五六万的变则双面进张，就能迅速判断。切九万后，七万与八万仍能补救。索子嵌张若直接补上，就切六筒立即立直。"],"discard":"9m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":213,"question_pdf":164,"answer_pdf":165,"question_printed":159,"answer_printed":160,"hand":["1m","2m","3m","2p","4p","0p","6p","7p","9p","2s","3s","4s","5s"],"draw":"7s","meta_ocr":"东1局 東家 5巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora213.webp","translation":["宝牌2的一向听，自己是庄家，即使愚形听牌，也希望抢先立直压制他家。切九筒、向内整理并观察三色似乎不错，但更常见的是三色完成前就已听牌。只比较最终听筒子时的形，保留靠近边端的等待，切二筒正确。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":214,"question_pdf":166,"answer_pdf":167,"question_printed":161,"answer_printed":162,"hand":["6m","7m","8m","9m","1p","1p","1p","2p","4p","4s","0s","7s","7s"],"draw":"7s","meta_ocr":"7巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora214.webp","translation":["单看进张，切九万更多，但最终听嵌三筒较困难。切四筒则必定得到好形听牌。"],"discard":"4p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":215,"question_pdf":166,"answer_pdf":167,"question_printed":161,"answer_printed":162,"hand":["3m","3m","4m","7m","7m","5p","7p","7p","1s","1s","6s","7s","8s"],"draw":"6p","meta_ocr":"束1局 東家 9巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora215.webp","translation":["本想拆一索对子转断幺九，但已第9巡。应固定两面，只保留好形最终形，维持一向听；如果七筒靠张，就再拆一索。宝牌七万当然要碰，六筒若能吃也尽量吃。"],"discard":"3m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":216,"question_pdf":166,"answer_pdf":167,"question_printed":161,"answer_printed":162,"hand":["2m","3m","4m","4m","5p","6p","7p","8p","3s","4s","5s","6s","7s"],"draw":"3s","meta_ocr":"東1局 西家 7巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora216.webp","translation":["按原书补充图分组，就容易看清。索子既能作“雀头加一个面子”，也能作“两个面子”，延伸后还可能兼顾雀头与两个面子，十分灵活。亚两面与四连形相比，四连形更强；手里已有这种便利结构时，拆掉亚两面，通常较容易正确。"],"discard":"4m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":217,"question_pdf":168,"answer_pdf":169,"question_printed":163,"answer_printed":164,"hand":["2m","3m","3m","0m","3p","4p","5p","6p","6p","5s","6s","7s","8s"],"draw":"7p","meta_ocr":"5巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora217.webp","translation":["切二万退回两向听，乍看不错；但兼具赤牌与宝牌的赤五万不能切，索子即使延伸也没有意义。应拆索子，不放弃摸四万直接听牌的机会。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":218,"question_pdf":168,"answer_pdf":169,"question_printed":163,"answer_printed":164,"hand":["2m","2m","5m","5m","4p","5p","2s","3s","5s","6s","6s","7s","8s"],"draw":"9s","meta_ocr":"東1局 東家 5巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora218.webp","translation":["依五组理论拆掉一个弱搭子，即延伸较少的二万搭子。不能切六索：既会保留六组，四索进张也会重复。"],"discard":"2m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":219,"question_pdf":168,"answer_pdf":169,"question_printed":163,"answer_printed":164,"hand":["3m","5m","6m","7m","3p","3p","4p","4p","7p","8p","2s","4s","4s"],"draw":"9p","meta_ocr":"东1局 西家 4巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora219.webp","translation":["摸九筒会破坏断幺九。单看宽度是切三万，但若索子先完成，就会留下无宝牌、无役的听牌，立直也令人犹豫。不如一开始只保留有役听牌的路线，灵活推进。切二索后，三索虽成为损失，但摸二筒、五筒可得高目平和一杯口；三万若靠张，再从三三四四索双重面子拆一枚，就形成完全一向听。现代打法中，一开始就直接拆三四筒，通常不被看好。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":220,"question_pdf":170,"answer_pdf":171,"question_printed":165,"answer_printed":166,"hand":["3m","4m","7m","8m","9m","7p","8p","8p","9p","3s","4s","5s","6s"],"draw":"4m","meta_ocr":"8巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora220.webp","translation":["固定宝牌雀头会太慢，这里切宝牌、保留宽进张。切三万也较宽，但筒子除宝牌八筒与指示牌七筒之外，没有特别令人高兴的摸牌，是其弱点。万子还存在赤牌进张，应保留。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":221,"question_pdf":170,"answer_pdf":171,"question_printed":165,"answer_printed":166,"hand":["2p","4p","5p","6p","7p","7p","8p","8p","1s","2s","3s","7s","8s"],"draw":"4p","meta_ocr":"東1局 東家 6巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora221.webp","translation":["切八筒后，筒子看似成为可进三筒、六筒、九筒的两面嵌张变形，实际上是陷阱：一杯口消失，摸到第三枚宝牌也难处理。直接切二筒既更宽，打点也更好。"],"discard":"2p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":222,"question_pdf":170,"answer_pdf":171,"question_printed":165,"answer_printed":166,"hand":["2m","3m","3m","4m","1p","1p","5p","7p","7p","4s","5s","7s","8s"],"draw":"9s","meta_ocr":"东1局 西家 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora222.webp","translation":["若只求眼前速度，应切三万，但很容易最终无役、无宝牌且愚形。这里切七筒，观察筒子两面变化与万子延伸。虽看似违背两雀头理论，但切五筒、维持两个雀头，也只有八筒一种两面变化。直接摸六筒听牌还能有平和，也很重要。"],"discard":"7p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":223,"question_pdf":172,"answer_pdf":173,"question_printed":167,"answer_printed":168,"hand":["3p","5p","8p","9p","2s","4s","7s","7s","8s","8s","8s","1z","1z"],"draw":"9p","meta_ocr":"4巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora223.webp","translation":["当前六组、搭子过多，又主要依赖双东，应在这里保留重视鸣牌效率的五组。"],"discard":"2s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":224,"question_pdf":172,"answer_pdf":173,"question_printed":167,"answer_printed":168,"hand":["3m","4m","6m","6m","6m","6m","7m","3p","4p","5p","7s","7s","7s"],"draw":"5m","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora224.webp","translation":["很多人可能切六万，取二五八万及七万四面听；但切三万，也能取四七万及五八万四面听，并包含宝牌四万，打点更有利。实战可按局面区分，期望值排序为切三万优于切六万，切六万优于切七索。切三万后立直。"],"discard":"3m","shanten":0,"comparisons":[],"terms":[],"action":"riichi"},{"id":225,"question_pdf":172,"answer_pdf":173,"question_printed":167,"answer_printed":168,"hand":["1m","1m","3m","3m","1p","2p","3p","4p","7p","4s","5s","6s","7s"],"draw":"9p","meta_ocr":"东1局 北家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"北家","turn":6,"special":"","dora_image":"images/dora225.webp","translation":["某本何切书把切三万、退回两向听作为正确答案，但这里更推荐直接保留一向听。切三万并不保证最终好形；直接摸八筒，取双碰听立即立直即可，索子若延伸，也可在三万对子与筒子嵌张之间再选择。当前就切三万，是过分追求好形、反而拖慢速度。"],"discard":"1p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":226,"question_pdf":174,"answer_pdf":175,"question_printed":169,"answer_printed":170,"hand":["1m","2m","2m","3m","4m","6m","1p","2p","3p","8p","8p","3s","4s"],"draw":"4m","meta_ocr":"6巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora226.webp","translation":["切二万进张最多，但与切一万只差1枚。考虑打点，应保留一杯口；若摸四筒，还能观察234三色。"],"discard":"1m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":227,"question_pdf":174,"answer_pdf":175,"question_printed":169,"answer_printed":170,"hand":["2p","3p","3p","4p","4p","4p","7p","7p","8p","3s","4s","4s","5s"],"draw":"3p","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora227.webp","translation":["把二三三三四四四筒按横向顺子，而非纵向刻子理解，就能看出答案。摸二筒、五筒可成断幺平和一杯口，索子进张听牌也一定能取两面立直。有效牌最多，又最不容易破坏断幺九，是没有明显缺点的一手。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":228,"question_pdf":174,"answer_pdf":175,"question_printed":169,"answer_printed":170,"hand":["1m","1m","1m","5m","6m","6m","4p","5p","5p","2s","2s","3s","7s"],"draw":"8s","meta_ocr":"东1局 西家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora228.webp","translation":["乍看该固定某组两面，其实有四个雀头候选，也有七对子机会，因此固定雀头进张最多；虽少见，也可能三暗刻。无论速度还是打点，固定雀头都更有利。比较五万、四筒、三索后，兼顾最终形与赤牌，切四筒正确。"],"discard":"4p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":229,"question_pdf":176,"answer_pdf":177,"question_printed":171,"answer_printed":172,"hand":["1m","1m","3m","5m","6m","6m","8m","4p","4p","7p","8p","4s","0s"],"draw":"4m","meta_ocr":"4巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora229.webp","translation":["三个雀头候选，依“三雀头最弱理论”，拆对子有2枚优势。先拆一枚一万，之后根据摸牌，向断幺九、三色或一气通贯发展。"],"discard":"1m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":230,"question_pdf":176,"answer_pdf":177,"question_printed":171,"answer_printed":172,"hand":["0m","6m","6m","2p","3p","4p","4p","5p","6p","8p","4s","5s","5s"],"draw":"3p","meta_ocr":"東1局 東家 8巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":8,"special":"","dora_image":"images/dora230.webp","translation":["关键在于是否保留嵌七筒进张。庄家第8巡，已有赤1且断幺九基本确定，应直接保留一向听。切六万既保留摸七筒直接听牌，也避免被迫打出赤牌；筒子若重成对子，结构同样会改善，十分灵活。"],"discard":"6m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":231,"question_pdf":176,"answer_pdf":177,"question_printed":171,"answer_printed":172,"hand":["3m","4m","5m","6m","8m","3p","3p","8p","8p","9p","3s","3s","5s"],"draw":"7m","meta_ocr":"东1局 西家 4巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora231.webp","translation":["某本何切书推荐切三筒。但把浮牌留下来追遥远三色，受到推崇的是昭和时期；现代麻将不会勉强追远三色，也不推荐这种留浮牌方式。直接切九筒、一路食断也可以，不过巡目还早，依“三雀头最弱理论”，切三索既保留宝牌七筒进张，也更容易鸣牌、适应变化。之后三筒若靠张，再切九筒追三色。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":232,"question_pdf":178,"answer_pdf":179,"question_printed":173,"answer_printed":174,"hand":["1m","2m","6m","8m","2p","3p","7p","8p","4s","4s","5s","7s","7s"],"draw":"5s","meta_ocr":"3巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora232.webp","translation":["搭子过多，拆掉最弱的边张即可。不要只因索子重复进张，就拆四索或五索。"],"discard":"1m","shanten":3,"comparisons":[],"terms":[],"action":"discard"},{"id":233,"question_pdf":178,"answer_pdf":179,"question_printed":173,"answer_printed":174,"hand":["2m","3m","4m","4m","5m","6m","8m","3p","4p","5p","5p","7p","8p"],"draw":"2m","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora233.webp","translation":["切五筒，万子保留二万、五万、八万、七万进张，必定平和。切八万后摸八筒虽会嵌张听，其他有效牌却全部能做平和。两者都很强，但切八万有摸六筒形成三面听，以及摸赤五筒的机会，期望值最高。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":234,"question_pdf":178,"answer_pdf":179,"question_printed":173,"answer_printed":174,"hand":["6m","8m","4p","5p","6p","7p","8p","9p","3s","3s","0s","1z","1z"],"draw":"3p","meta_ocr":"东1局 西家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora234.webp","translation":["虽然退回两向听，仍应保留强形。拆筒子、维持一向听，因役牌是对子，直线推进很容易被迫切掉赤五索。这里应以退为进：把七八九筒分开看，剩下三四五六筒四连形，很快就可能再组成两面；即使退两向听，三筒、六筒、九筒重成对子，也能留下相当强的结构。"],"discard":"8m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":235,"question_pdf":180,"answer_pdf":181,"question_printed":175,"answer_printed":176,"hand":["3m","0m","6m","7m","5p","5p","6p","7p","6s","6s","7s","7s","8s"],"draw":"9s","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora235.webp","translation":["序盘可以考虑切九索，但现在第7巡，要平衡宽度、打点和最终形。保留既能利用宝牌三万靠张，也能利用它重成对子的结构，就是正确方向。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":236,"question_pdf":180,"answer_pdf":181,"question_printed":175,"answer_printed":176,"hand":["3m","4m","7m","8m","1p","4p","2s","3s","4s","6s","8s","1z","4z"],"draw":"5m","meta_ocr":"束1局 南家 13 巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"南家","turn":13,"special":"","dora_image":"images/dora236.webp","translation":["好配牌，已完成两个面子，但尚无雀头，也接近平和，应细致地先切役牌。虽然少见，一四筒这种愚形若接连摸到二筒、三筒，也会形成延边，雀头并不难产生。"],"discard":"1z","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":237,"question_pdf":180,"answer_pdf":181,"question_printed":175,"answer_printed":176,"hand":["1m","1m","3m","4m","0m","5m","6m","7m","7m","7m","4p","4s","4s"],"draw":"0s","meta_ocr":"東1局 南家 5巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"南家","turn":5,"special":"","dora_image":"images/dora237.webp","translation":["固定兼具赤牌与宝牌的赤五索。现在已有14枚有效牌，不应切一万、一口气强转断幺九。若选择切一万，可能有“断幺九病”；七万对子应等四筒靠张后再拆。当前可视为三个雀头候选，切四索与四筒的进张其实只差2枚，连指示牌也计入则只差1枚。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":238,"question_pdf":182,"answer_pdf":183,"question_printed":177,"answer_printed":178,"hand":["6m","7m","8m","4p","5p","6p","6p","7p","2s","2s","4s","4s","6s"],"draw":"6s","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora238.webp","translation":["二二四四六六索称为“跳对子”。拆中间的四索，摸二索、三索、五索、六索，都能形成一个雀头加一个面子。记住原则：跳对子切中间。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":239,"question_pdf":182,"answer_pdf":183,"question_printed":177,"answer_printed":178,"hand":["3m","4m","5m","3p","4p","4p","4p","5p","3s","3s","5s","5s","7s"],"draw":"7s","meta_ocr":"束1局 6巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora239.webp","translation":["这是非常少见的例外，不应机械照搬“跳对子切中间”而切五索。切三索后，摸六索也能有三色，默听5200确定。筒子变化时，与切五索相比最多损失4枚，但产生差别的进张会破坏三色。另有可以碰五索的优势。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":240,"question_pdf":182,"answer_pdf":183,"question_printed":177,"answer_printed":178,"hand":["2m","4m","5p","6p","6p","6p","7p","2s","2s","4s","4s","6s","6s"],"draw":"4p","meta_ocr":"东1局 西家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora240.webp","translation":["可瞄准三暗刻、七对子与一杯口。从二二四四六六索的跳对子中切四索虽然灵活，但切二万后，再前进一步的结构更强。四索等前进一步再切也不迟；同样是嵌张，留下四索还有一杯口价值。如果拆索子，可能没看出筒子重成对子后的七对子机会。"],"discard":"2m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":241,"question_pdf":184,"answer_pdf":185,"question_printed":179,"answer_printed":180,"hand":["4m","0m","7m","8m","3p","3p","5p","5p","7p","7p","8p","8p","8p"],"draw":"9m","meta_ocr":"束1局 5巡目 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora241.webp","translation":["切宝牌五筒最宽，但后续可能必须把两枚宝牌都拆掉。切三筒后摸六筒、切七筒后摸四筒，分别会错过直接听牌；不过切三筒遇到反向的六筒，以及摸九筒时，都还能瞄准一杯口。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":242,"question_pdf":184,"answer_pdf":185,"question_printed":179,"answer_printed":180,"hand":["0m","6m","2p","2p","5p","7p","4s","5s","5s","6s","7s","7s","9s"],"draw":"9s","meta_ocr":"束1局 4 巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora242.webp","translation":["宝牌是九索，可以做鸣牌三色，却不能食断。搭子过多，应依五组理论拆弱组。乍看想为567三色切七索，但接着摸三索或六索，还是得拆二筒对子；不如现在就切二筒，后面更容易保留强形。这样明显的直接反向损失，只有再摸二筒。"],"discard":"2p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":243,"question_pdf":184,"answer_pdf":185,"question_printed":179,"answer_printed":180,"hand":["4m","5m","3p","4p","5p","6p","6p","8p","8p","6s","6s","7s","7s"],"draw":"7s","meta_ocr":"东1局 西家 6巡目","banner_y":1485,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora243.webp","translation":["切八筒在摸二筒、五筒、四筒时更强，因此正确。也有很多人切六筒，其优点是摸三万、六万后双碰立直，更容易诱出八筒。但麻将有一发和自摸，切八筒保留三面听、一杯口与完全一向听的价值，超过这种诱导收益。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":244,"question_pdf":186,"answer_pdf":187,"question_printed":181,"answer_printed":182,"hand":["2m","3m","4m","5m","6m","7m","5p","2s","3s","4s","7s","7s","8s"],"draw":"4m","meta_ocr":"束1月 束家 6巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora244.webp","translation":["万子四五六七可视为好形四连形。若能形成三面听，或门前断幺平和，即使切掉双重宝牌赤五筒，也值得。摸一万、九万等不值得为其切赤五筒的牌，则直接摸切。"],"discard":"8s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":245,"question_pdf":186,"answer_pdf":187,"question_printed":181,"answer_printed":182,"hand":["3m","4m","6m","7m","2p","2p","4p","5p","6p","7p","7p","1s","1s"],"draw":"5m","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora245.webp","translation":["切二筒进张更宽，但万子形很好，最终很可能成为无役愚形听牌。此时应转为更容易鸣牌的断幺九。这样二万、五万、六万先进入时，也能选择默听。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":246,"question_pdf":186,"answer_pdf":187,"question_printed":181,"answer_printed":182,"hand":["2m","3m","4m","4p","0p","7p","9p","9p","4s","4s","5s","7s","9s"],"draw":"6p","meta_ocr":"东1局 東家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora246.webp","translation":["直接摸嵌八索，可形成平和听牌；筒子若延伸，再拆索子嵌张。不同风格也可能直接切七筒或九索，但本题九筒是指示牌，已占用1枚，那两种切法的优势被削弱。实战也应掌握尽量避开薄进张、同时推进手牌的组合技巧。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":247,"question_pdf":188,"answer_pdf":189,"question_printed":183,"answer_printed":184,"hand":["2m","2m","3m","3m","0m","7m","7m","6p","7p","8p","2s","4s","4s"],"draw":"4m","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora247.webp","translation":["为避免赤五万被迫打出，容易想切二万；但这里切二索正确。不仅有效牌最多，摸六万还能形成高目断幺平和一杯口，打点也更好，鸣牌同样容易应对。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":248,"question_pdf":188,"answer_pdf":189,"question_printed":183,"answer_printed":184,"hand":["1m","3m","5m","5m","6m","1p","1p","2p","3p","3p","3p","4p","5p"],"draw":"4m","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora248.webp","translation":["切宝牌一万当然最宽，但很容易留下嵌二筒，这是弱点。留下宝牌、切三筒后，摸宝牌一万或二万也能听牌，最终基本是平和。"],"discard":"3p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":249,"question_pdf":188,"answer_pdf":189,"question_printed":183,"answer_printed":184,"hand":["2m","4m","6m","8m","8m","0p","5p","7p","9p","5s","6s","1z","1z"],"draw":"1z","meta_ocr":"东1局 西家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora249.webp","translation":["切二万与九筒进张最多，看似任意选即可，但碰牌后是否产生多余牌，差别很大。切九筒后碰八万，再切七筒便是好形；若切二万后碰八万，就要在四六万与七九筒两个嵌张间选择，产生多余牌。用“弱搭子三张组成理论”很容易理解。也应注意，原手牌万子有5张，是奇数；筒子有4张，是偶数。"],"discard":"9p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":250,"question_pdf":190,"answer_pdf":191,"question_printed":185,"answer_printed":186,"hand":["2m","4m","4m","4p","5p","6p","6p","6p","7p","4s","0s","7s","8s"],"draw":"8s","meta_ocr":"束1月 7巡目 南家","banner_y":339,"original_only":false,"round":"东1局","seat":"南家","turn":7,"special":"","dora_image":"images/dora250.webp","translation":["切二万，保留既能靠张又能鸣牌、仅三万算反向损失的形。乍看六索进张重叠，容易想切七索；但即使重复进张，两面依然很强。"],"discard":"2m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":251,"question_pdf":190,"answer_pdf":191,"question_printed":185,"answer_printed":186,"hand":["5m","7m","8m","8m","8m","3p","4p","4p","6p","7p","8s","9s","9s"],"draw":"9m","meta_ocr":"東1局 東家 9巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora251.webp","translation":["无论切哪一张，都有反向损失。切四筒遇到反向进张时，损害较小。筒子虽重复进张，两面依然强。犹豫时，先固定两面，通常能避开多数严重失误。"],"discard":"4p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":252,"question_pdf":190,"answer_pdf":191,"question_printed":185,"answer_printed":186,"hand":["3m","4m","4m","6m","6m","7p","7p","7p","8p","9p","3s","5s","5s"],"draw":"6p","meta_ocr":"东1局 東家 9巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":9,"special":"","dora_image":"images/dora252.webp","translation":["四个雀头候选，很想食断，但筒子不向低位延伸就难处理。最高形是四暗刻，不过四万是指示牌，只剩1枚，又有宝牌五万进张，所以万子希望按顺子使用。切七筒，既追顺子，也保留七对子，更灵活。"],"discard":"7p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":253,"question_pdf":192,"answer_pdf":193,"question_printed":187,"answer_printed":188,"hand":["3m","3m","5m","6m","6m","7m","8m","6p","7p","2s","2s","3s","4s"],"draw":"0s","meta_ocr":"5巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora253.webp","translation":["搭子过多，正确选择是切二索，摸六索可追567三色。但六索进入前，若筒子先重成对子等，就应放弃三色，直接保留厚实结构。切六万单看进张最多，却无法在摸五筒、八筒时取两面听，因此吃亏。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":254,"question_pdf":192,"answer_pdf":193,"question_printed":187,"answer_printed":188,"hand":["4m","0m","6m","8m","9m","9m","6p","7p","2s","4s","4s","5s","7s"],"draw":"7m","meta_ocr":"東1局 東家 3巡目","banner_y":912,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora254.webp","translation":["切二索、保留九万，摸三万、六万、九万时可切七索，转为完全一向听。切九万后，摸四索、三索也很强，但这两种进张，仍略少于三万、六万、九万三种。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":255,"question_pdf":192,"answer_pdf":193,"question_printed":187,"answer_printed":188,"hand":["7m","8m","3p","5p","5p","7p","7p","9p","5s","5s","6s","7s","8s"],"draw":"9s","meta_ocr":"东1局 東家 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora255.webp","translation":["瞄准789三色，依“一向听峰值理论”，应留下到一向听时最容易形成三色的结构。若选了五索或七筒，试着想象摸六筒后的形；它们都不容易在一向听时保留两个雀头。"],"discard":"3p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":256,"question_pdf":194,"answer_pdf":195,"question_printed":189,"answer_printed":190,"hand":["2p","2p","3p","4p","6p","8p","3s","5s","6s","6s","4p","?","?"],"draw":"?","meta_ocr":"6巡目 束1月 西家","banner_y":339,"original_only":true,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora256.webp","translation":["推荐切八筒，直接的反向损失只有七筒。相比切二筒，当前进张虽少1枚，但留下的结构更容易继续鸣牌、推进。"],"discard":"8p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":257,"question_pdf":194,"answer_pdf":195,"question_printed":189,"answer_printed":190,"hand":["5m","6m","6m","7m","2p","3p","3p","4p","4p","5p","6p","7s","8s"],"draw":"8s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora257.webp","translation":["乍看复杂，只要按原书补充图拆开理解，就相当于已经解出。固定八索雀头，瞄准万子或筒子靠张听牌。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":258,"question_pdf":194,"answer_pdf":195,"question_printed":189,"answer_printed":190,"hand":["1m","2m","2m","2m","3m","5m","7m","2p","2p","3p","5s","6s","2z"],"draw":"2z","meta_ocr":"东1局 南家 3巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"南家","turn":3,"special":"","dora_image":"images/dora258.webp","translation":["宝牌3，搭子过多。应以“会碰南、也能碰到南”为前提，保留强形。解决含役牌的这类题，可以先假定容易碰、而且必碰的一组，与门前也容易完成的强组，先行完成。本题前者是自风南，后者是二二三筒；实战也常是这两组先完成。想象这一点，便自然得出切七万。"],"discard":"7m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":259,"question_pdf":196,"answer_pdf":197,"question_printed":191,"answer_printed":192,"hand":["5m","1p","1p","6p","6p","6p","7p","3s","4s","5s","1z","1z","1z"],"draw":"6s","meta_ocr":"4巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora259.webp","translation":["若目标是靠张听牌，通常应切暗刻旁的浮牌；但本题役牌宝牌3，碰一筒或六筒后的形很强。切五万与七筒的进张只差3枚，考虑最终形，切五万正确。"],"discard":"5m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":260,"question_pdf":196,"answer_pdf":197,"question_printed":191,"answer_printed":192,"hand":["3m","4m","6m","8m","4p","4p","7p","7p","2s","3s","3s","5s","6s"],"draw":"7s","meta_ocr":"東1局 東家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora260.webp","translation":["搭子过多，又有三个雀头候选，拆对子当前更宽；但这是后续进张很容易反转的典型形。筒子对子虽然在筋上，仍应维持三个雀头。只要想象四筒或七筒向旁边延伸后的完全一向听，就能迅速切出八万。"],"discard":"8m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":261,"question_pdf":196,"answer_pdf":197,"question_printed":191,"answer_printed":192,"hand":["2m","3m","6m","7m","2p","4p","4p","9p","9p","4s","5s","7s","8s"],"draw":"9s","meta_ocr":"东1局 西家 4巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora261.webp","translation":["过去也曾推荐切四筒，以提高平和概率；只看平和容易程度，确实如此。但当前搭子过多，下一步若产生厚度，仍要整理二筒。以将会出现厚度为前提，现在先确定五组、拆较弱九筒对子，后面更强。"],"discard":"9p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":262,"question_pdf":198,"answer_pdf":199,"question_printed":193,"answer_printed":194,"hand":["1m","1m","7m","8m","5p","1s","2s","3s","4s","5s","6s","1z","1z"],"draw":"6p","meta_ocr":"束1月 束家 6巡目","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora262.webp","translation":["双东对子，加两枚宝牌，要在双东与平和间选择。现代打法越来越倾向放弃平和、切一万，不完全依赖双东；自然听牌就立即立直。七万、八万、赤五筒、六筒重成对子时，也可以准备碰听。"],"discard":"1m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":263,"question_pdf":198,"answer_pdf":199,"question_printed":193,"answer_printed":194,"hand":["1m","2m","4m","5m","6m","4p","5p","6p","9p","9p","6s","7s","7s"],"draw":"3p","meta_ocr":"束1局 7巡目 西家","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora263.webp","translation":["筒子形成四连形，有机会在这里完成两个面子。一二万边张之后大概会拆，但直接摸三万仍能听牌，因此要留到最后。切七索、固定两面，是做平和的基本处理。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":264,"question_pdf":198,"answer_pdf":199,"question_printed":193,"answer_printed":194,"hand":["4m","4m","5m","5m","6m","7m","8m","8m","9m","4p","5p","4s","5s"],"draw":"0s","meta_ocr":"東1局 西家 7巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora264.webp","translation":["只有切八万或四索能保持一向听，切九万会退到两向听，太慢。前两者的听牌进张相同，但切八万会限于门前，而且做三色时要打出宝牌。切四索可固定宝牌3，也能鸣牌；八万或赤五索出现时，不必犹豫，直接碰。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":265,"question_pdf":200,"answer_pdf":201,"question_printed":195,"answer_printed":196,"hand":["0m","4p","5p","5p","6p","6p","5s","5s","7s","8s","8s","7z","7z"],"draw":"6m","meta_ocr":"6巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora265.webp","translation":["放弃很难利用赤五万的七对子，整理成五组，瞄准门前断幺平和。"],"discard":"7z","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":266,"question_pdf":200,"answer_pdf":201,"question_printed":195,"answer_printed":196,"hand":["3m","5m","3p","4p","5p","5p","6p","7p","2s","4s","6s","7s","8s"],"draw":"8p","meta_ocr":"東1局 東家 5巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora266.webp","translation":["切五筒或八筒最宽，但考虑最终形，更想拆三五万或二四索嵌张。三五万有两种两面变化，二四索只有一种；摸五索后的三面听虽诱人，基本仍应优先变化种类更多的一组。为应对下巡摸五索，先切外侧二索。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":267,"question_pdf":200,"answer_pdf":201,"question_printed":195,"answer_printed":196,"hand":["2m","2m","4m","5m","6m","6m","8m","0p","6p","5s","5s","7s","8s"],"draw":"9s","meta_ocr":"东1局 東家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora267.webp","translation":["依两雀头理论，两个对子都应保留。有人认为嵌七万与三万、五索双碰的枚数相同，不如拆对子以保留筒子补救；但若预定筒子先完成便立即立直，三万、五索双碰略优于嵌七万。不考虑把五索留下作浮牌：与其等五索摸四索或六索后，才开始拆三五万，不如保留以后能形成完全一向听的结构。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":268,"question_pdf":202,"answer_pdf":203,"question_printed":197,"answer_printed":198,"hand":["1m","2m","3m","4m","2p","3p","4p","4p","1s","2s","3s","4s","5s"],"draw":"3m","meta_ocr":"5巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora268.webp","translation":["切五索，兼顾123与234三色。切四筒虽进张最多，却仍可能最终只有立直；这里值得追三色，并且一定能有平和。过去何切题常一味追三色，出现许多勉强路线；本题是少数在现代打法中仍成立的例子。"],"discard":"5s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":269,"question_pdf":202,"answer_pdf":203,"question_printed":197,"answer_printed":198,"hand":["2m","3m","4m","6m","7m","1p","1p","3p","7p","7p","9p","4s","5s"],"draw":"6s","meta_ocr":"束1局 東家 7巡目","banner_y":912,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora269.webp","translation":["切三筒或九筒，都能维持两个雀头，差别在内侧牌进入时。切九筒后，摸六筒可成完全一向听，摸四筒可转断幺九；切三筒则没有转断幺九的机会。"],"discard":"9p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":270,"question_pdf":202,"answer_pdf":203,"question_printed":197,"answer_printed":198,"hand":["1m","2m","2m","4p","6p","7p","8p","9p","2s","3s","3s","0s","6s"],"draw":"7s","meta_ocr":"东1局 東家 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora270.webp","translation":["关键是能否对嵌五筒听立即立直。考虑双重宝牌赤五筒，立直没有问题；既如此，就保留最快结构。半途而废地切三索，会少4枚有效牌。回报大、风险也较高，所以风格可能不同。若不喜欢宝牌嵌张立即立直，也应先切一万，再根据后续摸牌改组。"],"discard":"1m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":271,"question_pdf":206,"answer_pdf":207,"question_printed":201,"answer_printed":202,"hand":["3m","3m","5m","6m","7m","4p","5p","7p","8p","2s","2s","3s","5s"],"draw":"6s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora271.webp","translation":["搭子过多，设想下一步的完全一向听，保留强的五组。拆七八筒，但摸六筒还有567三色，所以先切八筒。"],"discard":"8p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":272,"question_pdf":206,"answer_pdf":207,"question_printed":201,"answer_printed":202,"hand":["2m","2m","6m","7m","8m","9m","9m","5p","6p","7p","3s","5s","5s"],"draw":"6s","meta_ocr":"束1局 6巡目 西家","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora272.webp","translation":["切三索直线推进，很可能最后只有立直。先拆一枚九万，以便摸六索、七索时转为断幺九。"],"discard":"9m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":273,"question_pdf":206,"answer_pdf":207,"question_printed":201,"answer_printed":202,"hand":["3m","3m","7m","7m","2p","3p","7p","8p","8p","2s","4s","6s","8s"],"draw":"4p","meta_ocr":"东1局 西家 4巡目","banner_y":1255,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora273.webp","translation":["有宝牌七万对子，能看到断幺九，应全力食断。以鸣牌为前提，保留三个雀头更强；特别不能切会使断幺九不稳定的八筒。索子二四六八索这种“四张隔张形”，应先拆一枚，变成普通两嵌。兼顾微小的234三色机会，留下二索、切八索。这也是弱搭子三张组成理论：把四张索子整理为三张后，下一步无论摸什么，都不易产生多余牌。"],"discard":"8s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":274,"question_pdf":208,"answer_pdf":209,"question_printed":203,"answer_printed":204,"hand":["0m","4p","5p","1s","2s","3s","4s","0s","5s","5s","6s","1z","1z"],"draw":"7m","meta_ocr":"4巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":4,"special":"","dora_image":"images/dora274.webp","translation":["嵌六万是瓶颈，最终应想象双东或食断这种可以鸣牌的役。双东当然要碰；若碰不到，也应能转向断幺九，因此现在切一索。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":275,"question_pdf":208,"answer_pdf":209,"question_printed":203,"answer_printed":204,"hand":["3m","3m","5m","6m","6m","7m","8m","3p","4p","5p","6p","2s","3s"],"draw":"0p","meta_ocr":"東1局 東家 5巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora275.webp","translation":["这是为反向进张预留补救的一手。即使摸到反向的四万，再切三万，也能变化为原书补充图所示、有效牌翻倍以上的一向听。"],"discard":"6m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":276,"question_pdf":208,"answer_pdf":209,"question_printed":203,"answer_printed":204,"hand":["1m","1m","9m","9m","9m","4p","5p","6p","7p","7p","2s","4s","6s"],"draw":"7s","meta_ocr":"东1局 東家 7巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora276.webp","translation":["过去何切常推荐切七筒、拆两嵌；本书则推荐拆索子嵌张。这样摸五筒、六筒可见一杯口，其他筒子进入时，厚度也不同。二索与四索先切哪一枚，差距不大；不过无论怎样推进，最终大概率只有立直，推荐更重视危险度，先切内侧。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":277,"question_pdf":210,"answer_pdf":211,"question_printed":205,"answer_printed":206,"hand":["2m","2m","3m","1p","3p","3p","4p","5p","6p","6p","7p","7s","8s"],"draw":"9s","meta_ocr":"6巡目 束1月层 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora277.webp","translation":["切二万后，筒子成为可进二筒、五筒、八筒的两面嵌张变形，必定有平和，也能应对宝牌一筒重成对子。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":278,"question_pdf":210,"answer_pdf":211,"question_printed":205,"answer_printed":206,"hand":["3m","5m","1p","3p","6p","8p","5s","7s","9s","3z","3z","6z","6z"],"draw":"6z","meta_ocr":"束1局 南家 4巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"南家","turn":4,"special":"","dora_image":"images/dora278.webp","translation":["搭子过多，依五组理论拆弱组。比较三五万、一三筒与六八筒；三五万有两种两面变化，应保留。再比较两组筒子，从鸣牌难易及作为最终等待时的荣和率看，应留下靠近边端的一组，拆六八筒，从外侧八筒开始。"],"discard":"8p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":279,"question_pdf":210,"answer_pdf":211,"question_printed":205,"answer_printed":206,"hand":["1m","2m","3m","6m","7m","6p","8p","8p","7s","7s","9s","6z","6z"],"draw":"8m","meta_ocr":"东1局 北家 9巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"北家","turn":9,"special":"","dora_image":"images/dora279.webp","translation":["三个雀头候选。门前推进时拆对子有利，鸣牌推进时保留三个雀头有利。役牌对子通常以鸣牌为前提，但现在已第9巡，要考虑宝牌发可能与他家各持两枚、互相碰不到，因此应按门前推进。重视最终形，比起嵌七筒，更愿留下嵌八索。"],"discard":"7s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":280,"question_pdf":212,"answer_pdf":213,"question_printed":207,"answer_printed":208,"hand":["1m","3m","7m","8m","5p","6p","7p","7p","9p","2s","4s","1z","1z"],"draw":"1z","meta_ocr":"3巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":3,"special":"","dora_image":"images/dora280.webp","translation":["双东加宝牌3，满贯已确定，应留下容易鸣牌、容易和牌的边端牌。现在搭子过多，不要因为没有雀头就先拆九筒，而应先向五组整理。"],"discard":"2s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":281,"question_pdf":212,"answer_pdf":213,"question_printed":207,"answer_printed":208,"hand":["4m","5m","7m","9m","4p","5p","6p","7p","3s","4s","5s","8s","8s"],"draw":"4s","meta_ocr":"東1局 南家 5巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"南家","turn":5,"special":"","dora_image":"images/dora281.webp","translation":["四五六七筒四连形，与四四四五索中膨形，是两种“两面的种子”。这里虽然退到两向听，仍应拆七九万嵌张。其余都是好形，因此更重视危险度，从内侧七万先切；切九万也可给90分。"],"discard":"7m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":282,"question_pdf":212,"answer_pdf":213,"question_printed":207,"answer_printed":208,"hand":["2m","2m","7m","8m","2p","4p","7p","8p","9p","9p","9p","0s","6s"],"draw":"3p","meta_ocr":"东1局 東家 6巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"东家","turn":6,"special":"","dora_image":"images/dora282.webp","translation":["因为要保留平和，实际比较二万与九筒。若顺利直接听牌，两者相同；但搭子重成对子、变成完全一向听时，会出现差别。例如摸七万：切九筒只增加二万、七万进张，共4枚；切二万则增加六筒、九筒、七万，共7枚。基本原则是保留连接更紧密的牌。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":283,"question_pdf":214,"answer_pdf":215,"question_printed":209,"answer_printed":210,"hand":["3m","4m","8m","8m","4p","5p","6p","8p","8p","4s","5s","8s","8s"],"draw":"9s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora283.webp","translation":["要拆哪个对子，应比较各自内侧牌进入后的形。索子能完成一个面子，筒子能形成三面听，万子最弱。注意不要只拆一枚八筒、为了三面听而半途而废地留下浮牌。"],"discard":"8m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":284,"question_pdf":214,"answer_pdf":215,"question_printed":209,"answer_printed":210,"hand":["6m","7m","6p","6p","8p","2s","2s","3s","3s","4s","5s","7s","7s"],"draw":"8s","meta_ocr":"東1局 西家 4巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora284.webp","translation":["当前两向听。不算七对子时，切六筒、二索、赤五索、七索都是31枚，切八筒、八索都是29枚。由于可视为三个雀头，拆对子当前较宽，但到一向听时容易被反超。切八筒后，下一张无论摸什么，都较不容易产生多余牌，结构厚实，期望值最高。"],"discard":"8p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":285,"question_pdf":214,"answer_pdf":215,"question_printed":209,"answer_printed":210,"hand":["5m","6m","2p","2p","3p","3p","4p","5p","5p","6p","4s","5s","6s"],"draw":"7s","meta_ocr":"东1局 東家 7巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora285.webp","translation":["已有两枚宝牌，不必同时追456与567两种三色，应固定索子一个面子，取最大进张。四索与七索之间，关键是摸四万、七万或四筒时，应切六筒，放弃三色、取高目一杯口。因此真正有差别的只有二筒、三筒、六筒：二筒与三筒共3枚，六筒4枚。无论打点平衡还是枚数，追567三色更有利。"],"discard":"4s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":286,"question_pdf":216,"answer_pdf":217,"question_printed":211,"answer_printed":212,"hand":["5m","6m","6m","6m","7m","2p","2p","3p","6s","6s","6s","7s","7s"],"draw":"8s","meta_ocr":"5巡目 束1月 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":5,"special":"","dora_image":"images/dora286.webp","translation":["留下六索对子后，最希望摸九索；切六索则拒绝这一路线，综合平衡更好。比起遥远的四暗刻，着眼于眼前断幺九、赤牌进张和一杯口，更容易获得高打点。"],"discard":"6s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":287,"question_pdf":216,"answer_pdf":217,"question_printed":211,"answer_printed":212,"hand":["1p","1p","2p","3p","3p","4p","5p","5p","6p","5s","6s","7s","8s"],"draw":"9s","meta_ocr":"東1局 西家 6巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora287.webp","translation":["切一筒与五筒最宽，而一筒是宝牌，因此切五筒更好。索子形成雀头后虽会嵌张听，但最终形成一四七筒三面听的可能性也很高。"],"discard":"5p","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":288,"question_pdf":216,"answer_pdf":217,"question_printed":211,"answer_printed":212,"hand":["5m","5m","7m","5p","6p","7p","7p","8p","8p","5s","6s","6s","7s"],"draw":"6m","meta_ocr":"东1局 西家 8巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":8,"special":"","dora_image":"images/dora288.webp","translation":["好形一向听，不应只数当前进张，要数能形成好形听牌的枚数，切五万便是正确答案。三色虽容易破坏，但即使切掉宝牌，也能形成门前断幺平和，庄家满贯以上确定。最差摸九筒，仍能确定三色。本题也体现了“犹豫时拆亚两面，通常正确”的原则。"],"discard":"5m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":289,"question_pdf":218,"answer_pdf":219,"question_printed":213,"answer_printed":214,"hand":["3m","3m","4m","5m","5p","6p","7p","8p","1s","1s","2s","2s","3s"],"draw":"4s","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora289.webp","translation":["发现这是靠张听牌题，就很简单：直接取最大进张。固定一索雀头、切二索正确。"],"discard":"2s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":290,"question_pdf":218,"answer_pdf":219,"question_printed":213,"answer_printed":214,"hand":["2m","2m","3m","3p","3p","6p","7p","8p","6s","7s","7s","8s","8s"],"draw":"8s","meta_ocr":"束1局 東家 7巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora290.webp","translation":["切二万进张最多。索子五索至九索全部能使手牌听牌，是很好的形，应完整保留。留下复杂部分、固定两面，通常就比较接近正确答案。"],"discard":"2m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":291,"question_pdf":218,"answer_pdf":219,"question_printed":213,"answer_printed":214,"hand":["3m","3m","5m","7m","9m","1p","1p","3p","5p","6s","7s","4z","4z"],"draw":"8m","meta_ocr":"东1局 西家 4巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora291.webp","translation":["三个雀头的两向听，以门前为前提。依“三雀头最弱理论”，从三个雀头拆成两个，当前进张多2枚。切一筒既宽，又能避免到一向听时产生多余牌，因此正确。也可用五组理论理解：把筒子分成一筒对子与三五筒，就有六组；拆一筒或五筒可无多余牌地整理为五组，再比较宽度，仍是切一筒。"],"discard":"1p","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":292,"question_pdf":220,"answer_pdf":221,"question_printed":215,"answer_printed":216,"hand":["3m","4m","4m","5m","6m","7m","8m","8m","6p","7p","8p","3s","4s"],"draw":"7m","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora292.webp","translation":["万子为八张翼形。虽然不能碰听，仍能吃听；26枚有效牌全部能形成两面听。"],"discard":"8m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":293,"question_pdf":220,"answer_pdf":221,"question_printed":215,"answer_printed":216,"hand":["4m","5m","6m","7m","9m","9m","6p","8p","4s","4s","8s","9s","9s"],"draw":"6s","meta_ocr":"東1局 西家 3巡目","banner_y":798,"original_only":false,"round":"东1局","seat":"西家","turn":3,"special":"","dora_image":"images/dora293.webp","translation":["三个雀头，宝牌九索为对子，按门前推进。把宝牌对子单独分开，就能看出四四六八索占了四张，应整理成三张。兼顾三色，保留两嵌形较好。"],"discard":"4s","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":294,"question_pdf":220,"answer_pdf":221,"question_printed":215,"answer_printed":216,"hand":["4p","4p","4p","0p","7p","8p","2s","2s","3s","3s","4s","5s","6s"],"draw":"7s","meta_ocr":"东1局 西家 6巡目","banner_y":1313,"original_only":false,"round":"东1局","seat":"西家","turn":6,"special":"","dora_image":"images/dora294.webp","translation":["切赤五筒或八筒，进张虽多，但打点很可能骤降。切三索才是正确答案，期望值和和牌率都最高。六筒重复进张，容易让人抗拒同时留下赤五筒与八筒，但四四四赤五七八筒已有15枚进张；再前进一步后，必定保留至少两面听。摸六筒甚至形成五面听，属于远超过普通重复进张的超好形。"],"discard":"3s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":295,"question_pdf":222,"answer_pdf":223,"question_printed":217,"answer_printed":218,"hand":["1m","2m","3m","4m","5m","7m","7m","4p","6p","7p","7s","8s","8s"],"draw":"3p","meta_ocr":"7巡目 束1月 束家","banner_y":339,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora295.webp","translation":["搭子过多，切一万进张最多，也保留六万进张，更容易有断幺九。可以对照体会，它与昭和风格切八索、维持六组的差别。"],"discard":"1m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":296,"question_pdf":222,"answer_pdf":223,"question_printed":217,"answer_printed":218,"hand":["7m","9m","9m","6p","7p","1s","2s","2s","4s","5s","6s","8s","9s"],"draw":"2s","meta_ocr":"東1局 北家 5巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"北家","turn":5,"special":"","dora_image":"images/dora296.webp","translation":["维持一向听只能切七万或一索。切七万可留一气通贯，但一通不确定；若七索先进入，也会直接立直，不再追一通。不如优先保留摸宝牌八索、摸八万直接完成面子的机会。"],"discard":"1s","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":297,"question_pdf":222,"answer_pdf":223,"question_printed":217,"answer_printed":218,"hand":["5m","5m","7m","6p","6p","7p","8p","8p","3s","3s","6s","6s","7s"],"draw":"8p","meta_ocr":"東1局 5巡目","banner_y":1427,"original_only":false,"round":"东1局","seat":"东家","turn":5,"special":"","dora_image":"images/dora297.webp","translation":["七对子一向听。只看宽度应摸切，但远处还有567三色与四暗刻。无论怎样切都有损失，应先想清最不愿错过什么；若最在意错过役满四暗刻，就应维持七对子一向听，同时随时能转向对对和系。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":298,"question_pdf":224,"answer_pdf":225,"question_printed":219,"answer_printed":220,"hand":["1m","3m","5m","6m","7m","4p","4p","6p","3s","4s","6s","6s","8s"],"draw":"1m","meta_ocr":"束1月 7巡目 西家","banner_y":339,"original_only":false,"round":"东1局","seat":"西家","turn":7,"special":"","dora_image":"images/dora298.webp","translation":["容易依“三雀头最弱理论”拆对子，但这里应固定宝牌对子。当前比拆对子少2枚，但若维持结构继续前进，到一向听时，进张宽度会反过来占优。"],"discard":"3m","shanten":2,"comparisons":[],"terms":[],"action":"discard"},{"id":299,"question_pdf":224,"answer_pdf":225,"question_printed":219,"answer_printed":220,"hand":["3m","5m","6m","7m","7m","8m","3p","4p","6p","6p","6p","3s","4s"],"draw":"5s","meta_ocr":"束1局 東家 7巡目","banner_y":855,"original_only":false,"round":"东1局","seat":"东家","turn":7,"special":"","dora_image":"images/dora299.webp","translation":["切宝牌三万最宽，但原本足以期待庄家满贯的手，最差会变成只有立直。这里切七万，最高形是断幺平和三色；即使宝牌重成对子，也能形成断幺九宝牌2听牌。切六筒的进张则大幅减少，不宜。"],"discard":"7m","shanten":1,"comparisons":[],"terms":[],"action":"discard"},{"id":300,"question_pdf":224,"answer_pdf":225,"question_printed":219,"answer_printed":220,"hand":["1m","2m","2m","4p","6p","8p","8p","9p","9p","4s","0s","5z","5z"],"draw":"3p","meta_ocr":"东1局 西家 4巡目","banner_y":1369,"original_only":false,"round":"东1局","seat":"西家","turn":4,"special":"","dora_image":"images/dora300.webp","translation":["四个雀头，七对子两向听；按普通面子手看，则为三向听且搭子过多。目标是整理成强的五组。三四筒、四赤五索与白对子都是强组，先确定为面子候选；再从一二二万与六八八九九筒中保留两组。这里切六筒正确，先留下八八九九筒的连续对子形；之后若无特殊情况，再拆一枚八筒，把筒子整理为八九九三张。"],"discard":"6p","shanten":2,"comparisons":[],"terms":[],"action":"discard"}],"reading_rules":[{"title":"宝牌显示的是指示牌","text":"题面展示的是宝牌指示牌，而非宝牌本身，与实战相同。指示牌保留为原书截图。"},{"title":"摸牌单独放在最右侧","text":"题面把新摸到的一枚放在手牌最右侧；原书答案页会将它放回手牌中。电子牌图也保留这一位置关系。"},{"title":"比较表中的数字是什么意思","text":"“切某牌 → N枚”表示切掉这枚后，能使手牌向听数下降的有效牌总枚数。表内仅列出原书选取的候选切牌，未列出所有切法。"},{"title":"有效牌枚数沿用原书的简化口径","text":"不扣除宝牌指示牌，也不扣除自己已经打出的牌；即使发生向听倒退，打出去的牌也当作原本就不存在。把刚切掉的牌又摸回来，也可能计为有效牌。因此数字用于牌效率比较，不等同于实战中的精确剩余牌数。"},{"title":"副露与特殊答案","text":"9道带副露的题目以完整原书题面为主，保留鸣牌方向。第132题推荐暗杠一索；第151—161题有“和牌即可取得第一名”的条件。"},{"title":"向听数与比较表","text":"中文状态标注采用推荐操作后的向听数；原书比较条的向听数可能对应其他候选切法。第69、161题推荐拆对子，会暂时退向听。"}],"glossary":[["赤","赤牌／红五","指赤五万、赤五筒、赤五索。"],["赤あり","有赤规则","使用赤牌的规则。"],["赤受け","赤牌进张","能利用摸入赤牌的结构。"],["アガリトップ","和牌即第一","最后一局只要和牌，无论点数多少都能取得第一。"],["亜リャンメン","亚两面","雀头紧连两面搭子的结构，如2234。"],["1シャンテンピーク理論","一向听峰值理论","提前组织手牌，使一向听阶段的有效牌尽可能多。"],["ウイング形","翼形","像展开双翼的结构，有8张与9张等类型；具体牌例见原书图。"],["浮かせ打ち","留浮牌打法","从对子切一枚，期待剩下一枚靠张的打法。"],["浮き牌","浮牌","单独孤立的一枚牌。"],["かわし手","抢和手","以快速和牌阻止他家和牌的手。"],["仮テン","暂时听牌","先取的临时听牌。"],["完全1シャンテン","完全一向听","有效牌达到最大的一向听结构；典型为两组已完成面子、两个两面及两个雀头候选。"],["期待値","期望值","本书特指“一人麻将练习机”计算的数值；见原书说明。"],["喰い替え","食替","鸣牌后，用鸣入的牌替换原有面子中的牌。"],["くっつき","靠张","期待孤立牌与新摸入牌连接的状态。"],["くっつきテンパイ","靠张听牌","孤立牌靠张后即可听牌的手。"],["形式テンパイ","形式听牌","主要为流局听牌罚符而取的无役听牌。"],["5ブロック","五组","四个面子加一个雀头。"],["5ブロック理論","五组理论","提早收敛为五组，并逐步充实各组。"],["最終形","最终形","最终的听牌结构。"],["弱ターツ3枚構成理論","弱搭子三张组成理论","弱搭子尽量保留为三张一组。"],["シャンポン","双碰听","两个对子各等一枚成刻的听牌。"],["シャンテン","向听数","距听牌还需推进的步数。"],["祝儀","祝仪","与点棒分开结算的筹码。"],["祝儀麻雀","祝仪麻将","一发、里宝牌、赤牌等可获得筹码的规则。"],["3ヘッド最弱理論","三雀头最弱理论","三个雀头候选的结构通常较弱。"],["先制リーチ","先制立直","本局第一个立直。"],["即リーチ","即立直","听牌后立刻宣布立直。"],["ターツ","搭子","再进一枚便可成为面子的两张牌。"],["ターツ選択","搭子选择","选择保留或拆除哪个搭子。"],["縦引き／横引き","重张／横向进张","摸到同种牌叠成对子等称重张；摸到相邻牌连接结构称横向进张。"],["打点","打点","和牌点数的高低。"],["ダブドラ","双宝牌","赤牌同时也是宝牌，一枚可算2番。"],["ダブルメンツ","双面子形","例如223344，可组成两组相同顺子。"],["ダマ","默听","已经听牌但不立直。"],["タンヤオ病","断幺九病","什么牌都想做断幺九的倾向。"],["チーテン","吃听","吃牌后听牌。"],["2ヘッド理論","两雀头理论","有两个雀头候选通常最有效率。"],["テンパイ効率","听牌效率","进入听牌的容易程度。"],["テンパイスピード","听牌速度","到第几巡能听牌的快慢。"],["点ハネ","升点","因符数向上取整等，使和牌点数提高。"],["ドラ単OK理論","宝牌单骑也可以理论","以最终能否接受宝牌单骑作为组织手牌的判断。"],["中ぶくれ","中膨形","如2334，中央重复、两侧相连的结构。"],["ネック","瓶颈","手牌的障碍或弱点。"],["ノベタン","延单骑","如3456，两端均可作雀头的两种单骑听牌。"],["のみ手","单役手","只有一个1番役的手。"],["牌効率","牌效率","尽量不浪费牌地组织手牌的技术。"],["離れリャンカン","离散两嵌","两组不直接相连、又能共同提供嵌张进张的结构；具体牌例见原书图。"],["ひっかけ","筋引诱","利用已舍牌的筋形成听牌，诱使对手打出和牌张。"],["フォロー牌","补充牌","除主要进张外，还能增加其他进张的牌。"],["複合形","复合形","面子与搭子交织的结构。"],["符ハネ","升符","符数向上取整而提高，原书视为与升点同义。"],["ブロック","组","面子、雀头或它们的候选结构。"],["ヘッド","雀头","也称将牌，一对相同牌。"],["ヘッドレス","无雀头","没有雀头的手牌。"],["ポン材","碰牌材料","可用于碰牌的对子等。"],["ポンテン","碰听","碰牌后听牌。"],["待ち","听牌张","听牌后等待的牌。"],["メンタンピン","立断平","立直、断幺九、平和；虽然使用“门”字，通常包含立直。"],["メンツ","面子","由三张牌组成的一组顺子或刻子。"],["メンツオーバー","搭子过多","面子候选加雀头候选合计六组以上。"],["役なし","无役","没有役的手。"],["余剰牌","多余牌","不增加有效牌的剩余牌。"],["4連形","四连形","如4567，可形成延单骑听牌的四张连续牌。"],["リャンカン","两嵌","如246，两组嵌张搭子合并的结构。"],["リャンメンカンチャン","两面嵌张","两面与嵌张交织的结构；原书列出8张复合形，具体牌例见原图。"],["両天秤","两路兼顾","同时追求两个役。"],["6ブロック打法","六组打法","直到较后阶段仍不收敛为五组的打法。"],["何切る","切哪一张","在给定手牌与局面下选择舍牌。"],["受け入れ","有效牌／进张","能让向听数下降的摸牌；本书的枚数有简化统计口径。"],["1シャンテン","一向听","再前进一步即可听牌。"],["シャンポン待ち","双碰听","保留两个对子，等待其中一种变成刻子。"],["カンチャン","嵌张","例如持四六，等待中间的五。"],["テンパネ","升点","符数增加并跨过计分档位，从而提高点数。"],["ピンフ","平和","日麻役名；本文用“平和”以免与“筒子”混淆。"],["タンヤオ","断幺九","只用二至八的数牌组成的役。"],["イーペーコー／リャンペーコー","一杯口／二杯口","门前的相同顺子组合役。"],["サンアンコー","三暗刻","拥有三个暗刻的役。"],["チートイツ","七对子","由七种不同对子组成的和牌形。"]],"extras":[{"pdf_page":7,"title":"前言：何切宅的心血300问（上）","paragraphs":["开端一如既往，颇为随意。作者乌扎库说：“至今还没有一本收录300道何切题的书，做出来一定会卖得好。”我回他说：“你说得对！”经不住他的积极推动，我答应试着做，结果从这里一路走得比预想远得多。","不要因为数量多，就以为这只是一本靠堆题取胜的书。题目质量也很高，每一道都经过反复推敲。乌扎库就是个何切宅：从各种书和漫画中大量收集题目，发现答案不对，就在博客上写下自己的修正。他是收集与核查方面的执着者。","他喜欢纠正别人，却不喜欢被别人纠正，所以本书尽量避开可能引起争论的题，直到最后都还在反复替换。同一技巧的题会减少，但重要技巧仍会在前后各保留一题，每题都认真筛选。","本书只收能得出明确答案的题，即强者会给出相同答案的题。除我和作者外，还请了两个人检查：ネマタ与タケオしゃん。ネマタ是《为了获胜的现代麻将技术论》的作者，头脑中似乎全是何切，可称这方面的第一人；タケオしゃん是网络麻将天凤的最高称号“天凤位”持有者。"]},{"pdf_page":8,"title":"前言：何切宅的心血300问（下）","paragraphs":["乌扎库指定这两位检查者，是因为他们总从实战角度思考，答案令人信服，也能结合传统与数理打法。经他们严格核查后，效果超出预期，题目终于缩小到“强者的标准答案应当如此”的范围。","信息量也很大。翻到答案页，就能看到每种候选舍牌的有效牌枚数，常会出现“拆两面，枚数竟然相同？”这样的意外结果。解析依数字展开，简洁明了。此前我没有见过这样的何切书。看似可以迅速做题，实际难题很多，并没有外表那么容易消化。一遍也有作用，反复练习效果更好。","对于最新打法，本书的讲解也相当充分。穿插的五组理论、两雀头理论、三雀头最弱理论、一向听峰值理论，名字虽不同，实际上有共通的思想，随着解题会逐渐深入。","它或许像一本何切定本，又像最终兵器。但在这样的书之后，未来是否还会有新何切书？我也有些担心，仿佛又建成了一条战术高速公路。不过这些都先放一边，请先随意打开一页，轻松地试着解题。所有事情都从这里开始。——福地诚，2016年7月。"]},{"pdf_page":10,"title":"专栏目录与人物介绍","paragraphs":["原书九组讲解专栏共14页：五组理论（第027、028、049页）；犹豫时固定两面（050）；两雀头理论（071、072）；三雀头最弱理论（113、114）；一向听峰值理论（135、136）；弱搭子三张组成理论（157）；宝牌单骑也可以理论（158）；四连形优于中膨形、优于亚两面（199）；留浮牌打法（200）。","姐姐“あかね”：麻将教室老师，周日也帮助雀庄工作。可靠，擅长做饭，憧憬美好的婚姻，不过条件是对方要比自己麻将强。","妹妹“あおい”：住在名古屋、性格开朗的大学生。网络麻将经验丰富，实体麻将暂时还不熟练，但正在快速成长。"]},{"pdf_page":11,"title":"本书使用方法","paragraphs":["题目显示的是宝牌指示牌，而非宝牌本身，与实战相同。新摸入的一枚放在手牌最右侧；答案页会把它整理回手牌。答案页也再次展示题面，并为主要候选舍牌标注有效牌枚数。","统计时不扣除宝牌指示牌。原书例中，若切一筒取听，因指示牌已占用一枚三索，实际和牌张本应为三索1枚加八索2枚，共3枚；书中仍写4枚，因为作者认为这样更便于学习牌效率。","统计也不扣除自己的舍牌。即使发生向听倒退，刚切掉的牌仍当作原本没有出现；将它再摸回来，只要能使向听数下降，也算有效牌。使用这些数字时，应理解其是用于牌形比较的简化口径。"]},{"pdf_page":32,"title":"五组理论①：四面子与一个雀头","paragraphs":["普通和牌需要四个面子与一个雀头。雀头只有两枚，但可与每组三枚的面子候选一起，把整手牌看成五组。原书例题尚未完成任何面子，却能分为六组，因此属于“搭子过多”。","既然最终只需要五组，要完成四面子加一雀头，就必定拆掉一组。应在当前阶段看远一步，先收敛为强的五组，这就是五组理论。它能显著改善听牌效率。插图旁的话：用理论武装自己，提高效率。"]},{"pdf_page":33,"title":"五组理论②：怎样选强组","paragraphs":["强组包括：容易完成面子的好形，如两面；直接提高打点的含宝牌结构；有助于三色、混一色等役的结构；役牌搭子；以及有补充牌的形，如三五五万。","弱组包括：难以完成面子的边张、嵌张；会破坏役的牌；以及剩余有效牌很少的进张。整手结构、场上信息和后续变化，也会改变强弱，但基本按这些标准选择要拆的组。","重看上一页例题，八九筒边张最弱，应拆掉它。插图旁的话：弱的组需要补充牌。"]},{"pdf_page":54,"title":"五组理论③：为什么不先固定两面","paragraphs":["看到例题，也许会想切六索、固定两面。实际上这是不收敛到五组、继续维持六组的打法。比较切八筒（或九筒）与六索：不算七对子，前者当前10种34枚，后者10种36枚。","按差分理解：切八筒、走五组，会失去七筒4枚进张；切六索、留六组，只失去六索2枚，所以当下固定两面看似有利。但它再前进一步就会不稳定。","分别想象摸中：先切八筒的牌姿A，再切九筒后，每张牌都发挥作用；先切六索的牌姿B，无论再切什么，仍是不稳定的六组，有一整组多余。先前多出的2枚，因还要拆一组而反转。A再切九筒有9种32枚，B最多切三万，仅7种28枚。因此一开始先收敛到五组更划算。"]},{"pdf_page":55,"title":"犹豫时固定两面","paragraphs":["复杂的部分应尽量保留。原书例题，无论怎样切都有反向损失；切六万在反向进张出现时损害较小。万子虽会重复进张，两面仍然强。","纸上何切可以慢慢研究，但实战有对手，不能总是长考。遇到各切法仅有细小差别的复杂形，与其耗费很长时间，不如先固定两面。这能避免大多数严重失误。","本书题目很多，建议尽量给自己设时间限制。比起每题都追求完美，实战更重要的是先消除严重舍牌错误。插图提醒：并不是任何时候都无条件固定两面。"]},{"pdf_page":76,"title":"两雀头理论①：两个雀头候选","paragraphs":["原书牌姿A是平和一向听，二筒对子是雀头候选。摸八索形成牌姿B，就是所谓完全一向听；此时八索也能作雀头，比A多4枚进张。把这种形称为“两个雀头候选”：二筒或八索任一种重成刻子，都能听牌。","以这种结构为理想形来推进，就是两雀头理论。两个候选中任意一个变成暗刻，另一个仍可作雀头；若只有一个候选，雀头变暗刻后，就得在别处另做雀头。","两个雀头候选很强。提前朝含两个雀头候选的好形一向听推进，是快速听牌的诀窍。插图旁的话：两个雀头，两段进攻。"]},{"pdf_page":77,"title":"两雀头理论②：成组保留的对子","paragraphs":["先给例题分组：相连的二万至九万折算三组，筒子一组、索子两组，合计六组，搭子过多，按五组理论应拆最弱的一组。万子好，还能见到一气通贯，不动；剩下筒子嵌张与两组索子对子。","三索对子既能作雀头，又有摸二索、四索两种两面变化，是强组。预想它变两面或变暗刻后，还需另一个雀头，所以八索对子也应成组留下；这就是两个雀头候选。","最后的六八筒嵌张只有一种两面变化，是弱组，应拆。为保留下一巡摸五筒变两面，先切八筒。插图旁的话：看似弱的对子，成组考虑也可能很强。"]},{"pdf_page":118,"title":"三雀头最弱理论①：第三个候选会多余","paragraphs":["由“两个雀头很强”延伸出的观点是“三个雀头较弱”。这里要用“松开对子”：从对子切一枚，仍使用另一枚。三个雀头时，松开一个变为两个，比维持三个，当前进张通常多2枚。","原书例题两向听，切四万或八索松开对子为20枚，其他所列候选都是18枚。2枚差距来自三个对子使双碰类进张重叠，所选舍牌造成的2枚差异便直接体现出来。也可从反向损失理解：有的切法失去对子剩下2枚，有的失去整种4枚。","松开哪一组，通常比较好形变化。切四万，万子有两种向两面变化的机会，又留下另外两个雀头；任意一个变暗刻，另一个仍能作雀头，因此本例切四万。","两个雀头强；三个雀头弱；四个及以上又出现七对子新路线，不能简单说弱。由此得到“三个最弱”的结论。"]},{"pdf_page":119,"title":"三雀头最弱理论②：适用条件与例外","paragraphs":["第一页例题即使初学者也容易切六索，但运用本理论，可把2枚差距也看清楚：切二筒与四筒差2枚，四筒与六索也差2枚。两面是强搭子，应固定；弱处留下补充牌。理解这2枚，也能结合场上舍牌，做更进一步的判断。","本理论能直接决定答案的结构，其实有限。例如依赖役牌的手，通常以鸣牌为主，三个雀头反而方便碰牌；原书第二例保留三个雀头、切二索更好。当前进张虽稍少，鸣牌却让三个雀头变强。","即使是门前手，两向听时松开对子，下一张摸牌也可能使一向听结构不稳定，或让有效牌枚数被反超。无须硬背全部例外，先记两点：当前进张，拆第三个雀头通常多2枚；三雀头最弱理论以门前推进为前提。"]},{"pdf_page":140,"title":"一向听峰值理论①：为最困难的阶段准备","paragraphs":["从三向听、两向听到一向听，有效牌逐渐减少。听牌时枚数最少，但还能荣和，多少有补偿。因此最困难的是一向听，应让这个阶段的进张尽可能多，这就是一向听峰值理论。","原书例题为三个雀头的两向听，断幺九已确定，也可追234三色。依三雀头最弱理论，拆二万、二筒或六索对子，当前较宽；但为了到一向听时，仍是无多余牌的含三色结构，应该现在切八索。","例如先切二万、取当下最大进张，接着摸三筒完成面子，就会发现八索完全无用，是多余牌。若先切八索，同样摸三筒并整理后，所有牌都在发挥作用。比较两者，先切二万的一向听没有补充牌，进张也被反超。因此要预先意识到：一向听时不要产生多余牌。"]},{"pdf_page":141,"title":"一向听峰值理论②：目标不同，答案不同","paragraphs":["原书例题两向听，应选择能在一向听阶段得到最好结构的一手。问题是，你最想要什么役？若最想断幺九，切九万；若最想平和，切七筒；若最想三色，切二索。","分别作上述切牌，再想象摸二筒进入一向听，原书列出A、B、C三种牌姿。比较就会发现，自己选择的役，恰好在对应牌姿中最容易完成。反复观察，记住应在两向听时怎样组织手牌。","本例的答案随目标而变。如果没有点棒状况等特殊理由，只按平衡与期望值判断，正确选择是切九万。插图旁的话：要能看见最终形。"]},{"pdf_page":162,"title":"弱搭子三张组成理论","paragraphs":["把一个面子候选尽量组成三张一组，前进时就不容易产生多余牌。原书第一个例题，固定雀头、切七筒当前最宽；但把万子弱搭子整理成三张更灵活。切二万，直接反向损失只有三万，下一张无论摸什么，都不易有多余牌。","不只是二四六八万，像四四六八万，也可切四万或八万、整理为三张。它的扩展观点是：万子、筒子等每种花色，保留5张、7张这样的奇数张，往往更好。","第二例比较切二万与二筒，当前进张最多且相同，但碰牌或摸六索后，结构会不同。万子原有4张、为偶数，筒子5张、为奇数；先拆万子一枚变为奇数，后续较不易出现多余牌。因此切二万，既维持两个雀头，也把万子整理为奇数。这里说的是弱搭子，强两面当然可只留两张。"]},{"pdf_page":163,"title":"宝牌单骑也可以理论","paragraphs":["宝牌能直接提高打点，却也可能被他家使用，成为危险牌。本理论的思路是：若最终只剩宝牌单骑，自己能不能接受？","原书例题已在中后盘，假定宝牌发一枚未见。手本身足够进攻，但看不到发令人不安，这时要预留以后摸发也不难处理的形。只要确定一杯口，哪怕最终单骑也可以，摸发就改为发单骑；若提前形成雀头、两面立直，也很好。","本例切六筒、取最大进张。虽然暂时失去雀头，确定役的价值很大。无论何时摸到宝牌，都能应对，是攻守兼顾的方式。相似牌形若无法确保至少1番，则通常应该先固定雀头。插图旁的话：有备无患。"]},{"pdf_page":204,"title":"四连形 ＞ 中膨形 ＞ 亚两面","paragraphs":["原书例题万子为中膨形，筒子为四连形，索子为亚两面。看似怎样切都能和牌，但最佳选择仍有差别。当前进张为切七万50枚、切三筒38枚、切四索46枚；切七万虽多，其中包含不少嵌张等愚形听牌。若比较两面听牌枚数，切四索更好。","做出好形听牌的诀窍，是分别计算留下某张牌后，哪些牌能形成两面听。例如留下四索，三索、五索两种可成两面；两种乘4枚，再扣自家使用，得到7枚。留下七万或三筒，则各有四种牌可形成两面听。","职业考试常问当前有效牌最多的是哪种，实战更需要问：形成好形听牌最多的是哪种？若好形听牌优先，通常保留顺序为四连形、中膨形、亚两面；若只看当前进张，则通常为四连形、亚两面、中膨形。三者混合又难判断时，拆亚两面往往正确。"]},{"pdf_page":205,"title":"留浮牌打法：适用与不适用","paragraphs":["“留浮牌”是从对子切一枚，观察另一枚的靠张，主要用于追求平和、三色。原书第一例是典型：切一筒或四筒可听牌，却切三索退回一向听，兼顾一气通贯与三色，这被视为出色处理。","过去流行把手牌组织得很“瘦”，留浮牌曾是高级技巧；现在更流行完全一向听这样的厚实结构，适用场合有限。本书除典型形外，基本不推荐，因难用且容易失败。本书拆对子，原则上是准备连续拆完。","第二例不能只为一气通贯先拆一枚八筒。其他部分产生厚度，如摸四万后，仍要继续拆八筒。不如瞄准完全一向听，留下两个能适应变化的雀头，先拆变化少的二索对子。即使后续重成对子而错过一通，仍能断幺九立直。牌效率尚未熟练时，可简单记作：只在拆听时考虑留浮牌。"]},{"pdf_page":228,"title":"后记：何切有正确答案吗？","paragraphs":["有人认为何切有正确答案，有人认为没有。排除出题者故意设置无解题，主要区别仍是麻将风格：一分也想和的人，与觉得1000点不够体面的人，舍牌自然不同。","本书以期望值为标准给出答案，因此有不少追求完全一向听的切法。但实战常需要留下安全牌，从这个角度看，何切只是高效进攻的基础训练与预演。","舍牌速度也重要。每手都在理论上达到100分很理想，但人不是机器。关键是避免明显错误；比起花时间追100分，持续在短时间作出80分的舍牌更好。虽常有人说牌效率难以拉开差距，但能快速、有效地判断，就能把精力用于其他因素，最终也会体现为差距。","何切有解吗？我的回答是：有的题有明确答案，也有的题没有，但所有题都应预先准备一个答案。这是为应对不同情况作准备，并不意味着一定要照解析切；已有自己的标准，可以优先使用；若没有，就先建立标准。","最后感谢参与核查的ネマタ、タケオしゃん，画插图的よっぴー，编辑福地、三才Books的梅田，以及此前在博客与Twitter回答何切的所有人。第一本书终于完成，感慨良多。——G・ウザク，2016年7月。"]},{"pdf_page":229,"title":"作者、编者与出版信息","paragraphs":["作者G・ウザク是麻将博客作者，年龄等详细资料未公开。博客的两大主题为何切与战术书评论；本书从约1000道发布过的题中筛选而成。他也认真记录、核查麻将书中的错误。麻将水平约为线下雀庄的现代派中等水平，居住于名古屋，还是拉面爱好者，在东海地区吃过1000家以上的拉面店。","编者福地诚是麻将作者兼编辑，几乎每年都有畅销麻将著作。除网络麻将外，也打高额雀庄麻将，自称雀庄职业牌手。1965年生于东京，毕业于京都大学教育学部。","书名：《麻雀 傑作「何切る」300選》。2016年8月5日第一刷，2016年8月20日第二刷。作者G・ウザク，编者福地诚，发行者塩见正孝，出版社三才Books。装帧与DTP：林健太郎；插图：よつば；校正：ネマタ、タケオしゃん；印刷装订：光邦。原书版权页完整保留于下方原图。"]}]};
